// Aptitude Quest question bank. Loaded with a plain <script src> so it works on file://.
// Schema: {id, topic, difficulty:1-3, q, o:[4], a:index, e, tip, why:[4 reasons aligned with o], data?:{headers, rows}}
window.QUESTIONS = [
{id:"quant-001",topic:"Quant",difficulty:1,q:"A 120 m train passes a pole in 6 seconds. What is its speed in km/h?",o:["54","20","72","80"],a:2,e:"120/6 = 20 m/s. Multiply by 3.6 to convert to km/h: 72.",tip:"m/s × 3.6 (or × 18/5) = km/h.",why:["Tempting if you slip on 120/6 and get 15 m/s, then convert correctly (15 x 3.6 = 54).","Tempting if you stop at 120/6 = 20 m/s and forget to convert to km/h (unit not converted).","Correct: 120/6 = 20 m/s, and 20 x 3.6 = 72 km/h.","Tempting if you round the 3.6 conversion factor up to 4 (20 x 4 = 80)."]},
{id:"quant-002",topic:"Quant",difficulty:1,q:"What is 20% of 250 plus 15% of 200?",o:["70","75","80","85"],a:2,e:"20% of 250 = 50 and 15% of 200 = 30. Total 80.",tip:"Find 10% by moving the decimal, then scale up.",why:["Tempting if you add the rates (35%) and apply them to 200 only: 35% of 200 = 70.","Tempting if you slip on 15% of 200, taking it as 25 instead of 30 (50 + 25).","Correct: 20% of 250 = 50 and 15% of 200 = 30, so 50 + 30 = 80.","Tempting if you compute 15% of 200 as 35 (adding 15 + 20) instead of 30."]},
{id:"quant-003",topic:"Quant",difficulty:1,q:"Two numbers are in the ratio 3:5 and add up to 64. What is the larger one?",o:["24","32","40","48"],a:2,e:"Total parts = 8, so each part = 8. Larger = 5 x 8 = 40.",tip:"Part value = total ÷ sum of ratio terms.",why:["Tempting if you answer with the smaller number (3 x 8 = 24) instead of the larger.","Tempting if you simply halve 64, ignoring the 3:5 ratio.","Correct: 3 + 5 = 8 parts, so one part = 8 and the larger is 5 x 8 = 40.","Tempting if you misread the ratio as 3:1 and take 3/4 of 64 = 48 (wrong number of parts)."]},
{id:"quant-004",topic:"Quant",difficulty:1,q:"Simple interest on $5,000 at 8% per year for 3 years?",o:["$1,000","$1,200","$1,299","$1,500"],a:1,e:"SI = P x R x T / 100 = 5000 x 8 x 3 / 100 = 1200.",tip:"8% of 5000 is 400 a year; times 3 years.",why:["Tempting if you use 2.5 years of interest, or treat the rate as 20% in total, rather than 8% x 3.","Correct: 8% of 5,000 = 400 per year, and 400 x 3 = 1,200.","Tempting if you compound the interest (5,000 x 1.08^3 - 5,000 = 1,298.56) when simple interest is asked.","Tempting if you round the rate up to 10% (500 x 3 = 1,500)."]},
{id:"quant-005",topic:"Quant",difficulty:2,q:"A can finish a job in 12 days, B in 6 days. Working together, how many days?",o:["3","4","5","9"],a:1,e:"1/12 + 1/6 = 3/12 = 1/4 of the job per day, so 4 days.",tip:"Together = (a × b) / (a + b) = 72 / 18.",why:["Tempting if you read the combined rate 3/12 as 3 days instead of inverting it to 12/3 = 4.","Correct: 1/12 + 1/6 = 3/12 = 1/4 of the job per day, so 4 days.","Tempting if you estimate between 4 and 6 days without adding the daily rates.","Tempting if you average the two times ((12 + 6)/2 = 9); times do not average, rates add."]},
{id:"quant-006",topic:"Quant",difficulty:1,q:"The average of five numbers is 24. Four of them are 20, 22, 26 and 28. What is the fifth?",o:["22","24","26","28"],a:1,e:"Total = 5 x 24 = 120. Known sum = 96. Fifth = 24.",tip:"Deviations from 24 (−4, −2, +2, +4) cancel, so the fifth is 24.",why:["Tempting if you misadd the known numbers as 98 (120 - 98 = 22).","Correct: total = 5 x 24 = 120, known sum = 96, so the fifth is 24.","Tempting if you misadd the known numbers as 94 (120 - 94 = 26).","Tempting if you assume the fifth must extend the pattern, or misadd the known sum as 92."]},
{id:"quant-101",topic:"Quant",difficulty:1,q:"A number increased by 25% becomes 150. What was the original number?",o:["120","112.5","125","187.5"],a:0,e:"Original x 1.25 = 150, so original = 150 / 1.25 = 120.",tip:"Undo a % increase by dividing by the multiplier, not by subtracting 25% of the new value.",why:["Correct: original x 1.25 = 150, so original = 150 / 1.25 = 120.","Tempting if you subtract 25% of 150 (150 - 37.5 = 112.5): wrong base for the percentage.","Tempting if you subtract 25 units instead of 25 percent (150 - 25 = 125).","Tempting if you apply the 25% increase again instead of reversing it (150 x 1.25 = 187.5)."]},
{id:"quant-102",topic:"Quant",difficulty:1,q:"An item bought for $400 is sold for $460. What is the profit percentage?",o:["13.04%","15%","60%","115%"],a:1,e:"Profit = 60; profit % = 60 / 400 x 100 = 15%.",tip:"Profit % is always on cost price unless stated otherwise.",why:["Tempting if you divide the profit by the selling price (60/460 = 13.04%): wrong base.","Correct: profit = 60, and 60/400 x 100 = 15% on cost price.","Reports the $60 profit itself as a percentage instead of dividing it by the $400 cost.","Tempting if you give SP as a percentage of CP (460/400 = 115%) instead of the profit percentage."]},
{id:"quant-103",topic:"Quant",difficulty:1,q:"A father is 3 times as old as his son. The sum of their ages is 48 years. How old is the father?",o:["32 years","16 years","36 years","12 years"],a:2,e:"Son = x, father = 3x, so 4x = 48, x = 12; father = 36.",tip:"Treat ages as ratio parts: 3:1 means 4 parts = 48.",why:["Misreads 'three times as old' as a 2:1 split of the total: 48 × 2/3 = 32.","Divides 48 by 3 (the multiplier) instead of by the 4 total parts (3 + 1).","Correct: son = x, father = 3x, so 4x = 48, x = 12 and the father is 36.","Tempting if you stop at x = 12, which is the son's age, not the father's."]},
{id:"quant-104",topic:"Quant",difficulty:1,q:"What is the LCM of 12, 18 and 30?",o:["90","360","60","180"],a:3,e:"12 = 2^2 x 3, 18 = 2 x 3^2, 30 = 2 x 3 x 5; LCM = 2^2 x 3^2 x 5 = 180.",tip:"LCM takes the highest power of every prime that appears.",why:["Tempting if you use only one factor of 2 (2 x 3^2 x 5 = 90); 12 needs 2^2.","Tempting if you include an extra factor of 2 (2^3 x 3^2 x 5 = 360), or take 12 x 30.","Tempting if you find the LCM of 12 and 30 only (60) and overlook 18's 3^2.","Correct: highest prime powers 2^2 x 3^2 x 5 = 180."]},
{id:"quant-105",topic:"Quant",difficulty:1,q:"Which of these numbers is divisible by 11?",o:["918082","918083","918092","918028"],a:0,e:"Alternating digit sums: (9+8+8) - (1+0+2) = 22, a multiple of 11.",tip:"Divisible by 11 if (sum of odd-place digits - sum of even-place digits) is 0 or a multiple of 11.",why:["Correct: (9 + 8 + 8) - (1 + 0 + 2) = 22, a multiple of 11.","Tempting because its alternating difference is 21, one off a multiple of 11.","Tempting because its alternating difference is 23, close to 22; it must be exactly a multiple of 11.","Tempting as a digit-swap of 918082 (same digit sum 28), but its alternating difference is 10."]},
{id:"quant-106",topic:"Quant",difficulty:1,q:"Two fair coins are tossed. What is the probability of getting at least one head?",o:["1/2","3/4","1/4","2/3"],a:1,e:"Only TT has no head, so P = 1 - 1/4 = 3/4.",tip:"For 'at least one', use 1 - P(none).",why:["Tempting if you count exactly one head (HT, TH = 2/4) and drop HH.","Correct: only TT has no head, so P = 1 - 1/4 = 3/4.","Tempting if you compute P(no head) or P(two heads) = 1/4 instead of the complement.","Tempting if you treat HT and TH as one outcome (3 cases, 2 with a head); outcomes are not equally likely."]},
{id:"quant-107",topic:"Quant",difficulty:1,q:"A rectangular plot is 15 m long and 8 m wide. What is its perimeter?",o:["23 m","120 m","46 m","38 m"],a:2,e:"Perimeter = 2 x (15 + 8) = 46 m.",tip:"Perimeter = 2(l + b); area (l x b) is the usual trap.",why:["Tempting if you add length and width (15 + 8 = 23) and forget to double.","Tempting if you compute area (15 x 8 = 120) instead of perimeter.","Correct: perimeter = 2 x (15 + 8) = 46 m.","Tempting if you double only the length (2 x 15 + 8 = 38)."]},
{id:"quant-108",topic:"Quant",difficulty:1,q:"A car covers 180 km in 3 hours 36 minutes. What is its average speed in km/h?",o:["60","53.6","45","50"],a:3,e:"3 h 36 min = 3.6 h; 180 / 3.6 = 50 km/h.",tip:"Convert minutes to decimal hours by dividing by 60 (36 min = 0.6 h).",why:["Tempting if you ignore the 36 minutes (180/3 = 60).","Tempting if you write 3 h 36 min as 3.36 h (180/3.36 = 53.6): minutes not converted.","Tempting if you round the time up to 4 hours (180/4 = 45).","Correct: 36 min = 0.6 h, so 180/3.6 = 50 km/h."]},
{id:"quant-109",topic:"Quant",difficulty:2,q:"The price of a shirt is raised by 20% and then the new price is reduced by 20%. What is the net change in price?",o:["4% decrease","No change","4% increase","2% decrease"],a:0,e:"1.2 x 0.8 = 0.96, so the price falls by 4%.",tip:"Successive +x% and -x% always give a net loss of x^2/100 %.",why:["Correct: 1.2 x 0.8 = 0.96, a net 4% decrease.","Tempting if you assume +20% and -20% cancel; the 20% cut applies to a larger base.","Tempting if you get the size right but the sign wrong; the second change acts on the higher price.","Tempting if you halve the x^2/100 rule (400/200 = 2%)."]},
{id:"quant-110",topic:"Quant",difficulty:2,q:"A shopkeeper marks goods 25% above cost price and then gives a 10% discount. What is his profit percentage?",o:["15%","12.5%","10%","17.5%"],a:1,e:"SP = 1.25 x 0.9 = 1.125 of CP, so profit = 12.5%.",tip:"Net % = a + b + ab/100 = 25 - 10 - 2.5 = 12.5.",why:["Tempting if you subtract the discount from the markup (25 - 10 = 15) and ignore the cross term.","Correct: SP = 1.25 x 0.9 = 1.125 of CP, so profit = 12.5%.","Tempting if you take the 10% discount figure itself as the net result.","Tempting if you add ab/100 with the wrong sign (25 - 10 + 2.5 = 17.5); with b = -10 the term is -2.5."]},
{id:"quant-112",topic:"Quant",difficulty:2,q:"The average age of 30 students is 40 years. When the teacher is included, the average rises to 41 years. What is the teacher's age in years?",o:["41","70","72","71"],a:3,e:"New total = 31 x 41 = 1271; old total = 1200; teacher = 71.",tip:"Newcomer = new average + (old count x rise) = 41 + 30 x 1.",why:["Tempting if you take the new average (41) as the teacher's age, forgetting the teacher lifts it.","Tempting if you add the total rise (30) to the old average 40 instead of the new average 41.","Tempting if you multiply the rise by the new count (41 + 31 = 72) instead of the old count of 30.","Correct: 31 x 41 = 1,271 minus 30 x 40 = 1,200 gives 71."]},
{id:"quant-113",topic:"Quant",difficulty:2,q:"What is the compound interest on $10,000 at 10% per annum for 2 years, compounded annually?",o:["$2,100","$2,000","$2,110","$1,210"],a:0,e:"Amount = 10000 x 1.1^2 = 12100, so CI = $2,100.",tip:"For 2 years, CI = SI + interest on first year's interest (2000 + 100).",why:["Correct: 10,000 x 1.1^2 = 12,100, so CI = 2,100.","Tempting if you use simple interest (1,000 x 2 = 2,000) and miss interest on interest.","Tempting if you add a further 10 of interest on interest (2,100 + 10), as if there were an extra compounding step.","Tempting if you misplace a zero on the amount 12,100 or the multiplier 1.21."]},
{id:"quant-114",topic:"Quant",difficulty:2,q:"A and B together can finish a job in 10 days. A alone can finish it in 15 days. How many days will B alone take?",o:["25","30","20","5"],a:1,e:"B's rate = 1/10 - 1/15 = 1/30, so 30 days.",tip:"B alone = (AB together x A) / (A - together) = 150 / 5.",why:["Tempting if you add the times (10 + 15 = 25) instead of subtracting rates.","Correct: B's rate = 1/10 - 1/15 = 1/30, so B alone takes 30 days.","Tempting if you assume A and B work equally fast, so each alone takes double (2 x 10 = 20).","Tempting if you subtract the times (15 - 10 = 5) instead of the rates."]},
{id:"quant-115",topic:"Quant",difficulty:2,q:"Two trains, 150 m and 100 m long, run on parallel tracks in opposite directions at 60 km/h and 40 km/h. How many seconds do they take to cross each other completely?",o:["15","45","9","22.5"],a:2,e:"Relative speed = 100 km/h = 250/9 m/s; time = 250 / (250/9) = 9 s.",tip:"Opposite directions: add speeds; distance = sum of both lengths.",why:["Tempting if you use only the faster train's speed (60 km/h = 16.67 m/s, 250/16.67 = 15).","Tempting if you subtract the speeds (20 km/h) as for the same direction (250/5.56 = 45).","Correct: relative speed 100 km/h = 250/9 m/s; 250 m / (250/9) = 9 s.","Tempting if you use only the slower train's speed (40 km/h = 11.1 m/s, 250/11.1 = 22.5)."]},
{id:"quant-116",topic:"Quant",difficulty:2,q:"A boat goes downstream at 16 km/h and upstream at 10 km/h. What is the speed of the stream in km/h?",o:["6","13","2","3"],a:3,e:"Stream = (16 - 10) / 2 = 3 km/h.",tip:"Boat speed = half the sum; stream speed = half the difference.",why:["Tempting if you take the difference (16 - 10 = 6) and forget to halve it.","Tempting if you compute the boat's speed in still water (half the sum = 13) instead.","Tempting if you divide the difference by 3 instead of 2 (6/3 = 2).","Correct: stream speed = (16 - 10)/2 = 3 km/h."]},
{id:"quant-117",topic:"Quant",difficulty:2,q:"A 40-litre mixture contains milk and water in the ratio 3:1. How many litres of water must be added to make the ratio 3:2?",o:["10","5","15","20"],a:0,e:"Milk = 30 L, water = 10 L. For 3:2 water must be 20 L, so add 10 L.",tip:"Keep the unchanged component fixed and rescale the ratio around it.",why:["Correct: milk 30 L stays fixed; 3:2 needs water of 20 L, so add 20 - 10 = 10 L.","Tempting if you misread the target as 2:1 (water 15 L for 30 L milk), so add 5.","Tempting if you misread the target as 6:5 (water 25 L for 30 L milk), so add 15.","Tempting if you give the final water amount (20 L) rather than the amount added."]},
{id:"quant-118",topic:"Quant",difficulty:2,q:"Two fair dice are thrown. What is the probability that the sum of the numbers is 8?",o:["1/6","5/36","1/9","7/36"],a:1,e:"Favourable: (2,6),(3,5),(4,4),(5,3),(6,2) = 5 of 36 outcomes.",tip:"Ways to get sum s with two dice = 13 - s for s from 7 to 12.",why:["Tempting if you use the count for sum 7 (6 ways, 6/36 = 1/6).","Correct: (2,6), (3,5), (4,4), (5,3), (6,2) = 5 of 36 outcomes.","Tempting if you leave out (4,4) and count only 4 ways (4/36 = 1/9).","Tempting if you apply the s - 1 rule (valid up to 7) to s = 8, giving 7/36."]},
{id:"quant-119",topic:"Quant",difficulty:3,q:"What is the remainder when 7^100 is divided by 5?",o:["2","3","1","4"],a:2,e:"7 = 2 (mod 5) and 2^4 = 16 = 1 (mod 5), so 2^100 = (2^4)^25 = 1.",tip:"Last digit of 7^n cycles 7, 9, 3, 1 every 4 powers; 100 is a multiple of 4.",why:["Tempting if you reduce 7 to 2 (mod 5) and forget the power.","Tempting if you misplace 100 in the 4-cycle (2, 4, 3, 1) and take the third term.","Correct: 7 = 2 (mod 5) and 2^4 = 1 (mod 5), so 2^100 = (2^4)^25 = 1.","Tempting if you misplace 100 in the 4-cycle and take the second term (2^2 = 4)."]},
{id:"quant-120",topic:"Quant",difficulty:3,q:"A man drives from A to B at 40 km/h and returns along the same road at 60 km/h. What is his average speed for the round trip in km/h?",o:["50","45","52","48"],a:3,e:"Average = 2 x 40 x 60 / (40 + 60) = 4800 / 100 = 48 km/h.",tip:"Equal distances: average speed = 2xy/(x + y), never the simple mean.",why:["Tempting if you take the simple mean (40 + 60)/2; more time is spent at 40 km/h.","Tempting if you sense the answer is below 50 but overcorrect toward the slower speed without computing.","Tempting if you weight each speed by itself ((1,600 + 3,600)/100 = 52) instead of by time.","Correct: equal distances give 2 x 40 x 60/(40 + 60) = 48 km/h."]},
{id:"quant-121",topic:"Quant",difficulty:3,q:"What is the difference between compound interest (compounded annually) and simple interest on $8,000 at 5% per annum for 3 years?",o:["$61","$60","$40","$20"],a:0,e:"CI = 8000 x (1.05^3 - 1) = 1261; SI = 1200; difference = $61.",tip:"For 3 years, CI - SI = P x (r/100)^2 x (3 + r/100).",why:["Correct: CI = 1,261 and SI = 1,200, so the difference is 61.","Tempting if you triple the 2-year gap (3 x 20 = 60) and miss the interest on that interest (+1).","Tempting if you double the 2-year gap (2 x 20 = 40) instead of using the 3-year formula.","Tempting if you use the 2-year shortcut P(r/100)^2 = 8,000 x 0.0025 = 20 for 3 years."]},
{id:"quant-122",topic:"Quant",difficulty:3,q:"Pipes A and B can fill a tank in 12 hours and 15 hours respectively, while pipe C can empty it in 20 hours. If all three are opened together on an empty tank, how many hours will it take to fill?",o:["8","10","5","6"],a:1,e:"Net rate = 1/12 + 1/15 - 1/20 = (5 + 4 - 3)/60 = 1/10, so 10 hours.",tip:"Take tank = LCM(12,15,20) = 60 units: rates 5 + 4 - 3 = 6 units/hour.",why:["Tempting if you subtract times (20 - 12 = 8) instead of combining rates.","Correct: 1/12 + 1/15 - 1/20 = (5 + 4 - 3)/60 = 1/10, so 10 hours.","Tempting if you add the emptying pipe's rate (5 + 4 + 3 = 12 units, 60/12 = 5) instead of subtracting it.","Tempting if you read the net 6 units per hour as 6 hours instead of 60/6 = 10."]},
{id:"quant-123",topic:"Quant",difficulty:3,q:"The present ages of A and B are in the ratio 5:7. Four years from now the ratio will be 3:4. What is B's present age in years?",o:["20","24","28","32"],a:2,e:"(5x + 4)/(7x + 4) = 3/4 gives 20x + 16 = 21x + 12, so x = 4 and B = 28.",tip:"Check options: B must be a multiple of 7 and (B + 4) a multiple of 4.",why:["Tempting if you give A's present age (5 x 4 = 20) instead of B's.","Tempting if you subtract 4 from B's age (28 - 4 = 24), applying the time shift the wrong way.","Correct: (5x + 4)/(7x + 4) = 3/4 gives x = 4, so B = 7 x 4 = 28.","Tempting if you give B's age four years from now (28 + 4 = 32)."]},
{id:"quant-124",topic:"Quant",difficulty:3,q:"A committee of 5 is to be chosen from 6 men and 4 women. In how many ways can this be done if the committee must have at least 3 men?",o:["120","180","246","186"],a:3,e:"6C3 x 4C2 + 6C4 x 4C1 + 6C5 = 120 + 60 + 6 = 186.",tip:"Split 'at least' into exact cases (3, 4, 5 men) and add.",why:["Tempting if you count only the exactly-3-men case (6C3 x 4C2 = 120).","Tempting if you count 3 and 4 men (120 + 60 = 180) but forget the all-men case (6C5 = 6).","Tempting if you use 10C5 - (1 man) = 252 - 6 and forget to remove the 2-men case (60).","Correct: 120 + 60 + 6 = 186."]},
{id:"quant-125",topic:"Quant",difficulty:3,q:"A closed cylinder has radius 7 cm and height 10 cm. What is its total surface area in sq cm? (Use pi = 22/7.)",o:["748","440","594","1540"],a:0,e:"TSA = 2 x pi x r x (r + h) = 2 x 22/7 x 7 x 17 = 748 sq cm.",tip:"Factor first: 2 x pi x r = 44 when r = 7, then multiply by (r + h).",why:["Correct: TSA = 2 x pi x r x (r + h) = 44 x 17 = 748 sq cm.","Tempting if you compute only the curved surface (2 x pi x r x h = 440).","Tempting if you add only one circular end (440 + 154 = 594) for a closed cylinder.","Tempting if you compute the volume (pi x r^2 x h = 1,540) instead of surface area."]},
{id:"logic-001",topic:"Logical",difficulty:2,q:"Find the next number: 2, 6, 12, 20, 30, ?",o:["38","40","42","44"],a:2,e:"Each term is n x (n+1): 1x2, 2x3, 3x4... the next is 6x7 = 42.",tip:"Check differences: 4, 6, 8, 10, so next is +12.",why:["Tempting if you reuse the earlier difference of 8 (30 + 8) instead of continuing the rising differences.","Tempting if you repeat the last difference of 10 (30 + 10) rather than increasing it to 12.","Correct: differences rise by 2 (4, 6, 8, 10), so the next is +12, i.e. 6 x 7 = 42.","Tempting if you jump the difference by 4 to 14 (30 + 14), skipping the +12 step."]},
{id:"logic-002",topic:"Logical",difficulty:1,q:"Which number is the odd one out: 3, 7, 9, 11?",o:["3","7","9","11"],a:2,e:"3, 7 and 11 are prime. 9 = 3 x 3 is not.",tip:"In number odd-one-outs, test for primes first.",why:["Tempting if you notice that removing 3 leaves 7, 9, 11 as consecutive odd numbers, a surface spacing pattern, but 3 is prime.","No clear rule isolates 7; it tempts only if you miscount 9 as prime and then guess among the rest.","Correct: 9 = 3 x 3 is the only non-prime; 3, 7 and 11 are all prime.","Tempting as the only two-digit number, a surface feature, but it shares the prime property with 3 and 7."]},
{id:"logic-003",topic:"Logical",difficulty:2,q:"All cats are animals. Some animals are pets. Is it true that some cats are pets?",o:["Definitely true","Definitely false","Cannot be determined","Probably true"],a:2,e:"The pets might all be dogs. The statements do not force any overlap with cats.",tip:"Two 'some/all' links through a middle group with no forced overlap: cannot be determined.",why:["Tempting because overlap seems natural, but 'some animals are pets' never forces those pets to be cats.","Tempting if you read 'some animals are pets' as excluding cats; nothing rules out cats being pets either.","Correct: the pets could all be dogs or all be cats, so the statements allow both outcomes.","Tempting because it sounds cautious, but a deductive verdict needs certainty; a likely overlap is still undetermined."]},
{id:"logic-004",topic:"Logical",difficulty:1,q:"If CODE is written as DPEF (each letter shifted by +1), how is GAME written?",o:["HBNF","HBMF","IBNF","GBNF"],a:0,e:"G→H, A→B, M→N, E→F gives HBNF.",tip:"Apply the rule to one letter at a time and eliminate options early.",why:["Correct: shifting each letter +1 gives G→H, A→B, M→N, E→F = HBNF.","Tempting if you skip a letter while shifting and leave M unchanged (HB M F).","Tempting if you shift the first letter by +2 (G→I) through a counting slip.","Tempting if you forget to shift the first letter and leave G unchanged."]},
{id:"logic-005",topic:"Logical",difficulty:1,q:"What is the angle between the clock hands at 3:00?",o:["60°","270°","90°","120°"],a:2,e:"Each hour mark is 30°, and the hands are 3 hours apart: 3 x 30 = 90°.",tip:"Angle = |30H − 5.5M|.",why:["Tempting if you count 2 hour gaps instead of 3 (off-by-one), giving 2 x 30 = 60°.","Tempting if you measure the reflex angle the long way round (360 - 90 = 270°) instead of the smaller angle.","Correct: the hands are 3 hour marks apart and each mark is 30°, so 3 x 30 = 90°.","Tempting if you count the marks 12, 1, 2, 3 as four steps (items, not intervals): 4 x 30 = 120°."]},
{id:"logic-101",topic:"Logical",difficulty:1,q:"Find the next number: 3, 9, 27, 81, ?",o:["162","243","324","189"],a:1,e:"Each term is 3 times the previous one, so 81 x 3 = 243.",tip:"If differences grow fast, check the ratio between terms.",why:["Tempting if you multiply by 2 instead of 3 (81 x 2), misreading the common ratio.","Correct: each term is 3 times the previous, so 81 x 3 = 243.","Tempting if you assume the multiplier keeps growing (x4), but the ratio is a constant 3.","Tempting if you work with differences (6, 18, 54) but double the last one: 81 + 108 = 189."]},
{id:"logic-102",topic:"Logical",difficulty:1,q:"Find the next letter: A, C, E, G, ?",o:["H","J","K","I"],a:3,e:"Letters move forward by 2 positions: G(7) + 2 = I(9).",tip:"Convert letters to positions (A=1) and look at the gaps.",why:["Tempting if you take the next letter (+1) and miss that the series skips one letter each time.","Tempting if you skip two letters (H, I) instead of one, giving a +3 step (G→J).","Tempting if you double the gap to +4 (G→K) without checking the constant step of 2.","Correct: positions 1, 3, 5, 7 rise by 2, so the next is 9 = I."]},
{id:"logic-103",topic:"Logical",difficulty:1,q:"In a certain code, MANGO is written as OGNAM. How is APPLE written in that code?",o:["ELPPA","EPLPA","ELPAP","APPEL"],a:0,e:"The code simply reverses the word, so APPLE becomes ELPPA.",tip:"Compare first and last letters to spot a reversal instantly.",why:["Correct: MANGO→OGNAM is a straight reversal, so APPLE reversed is ELPPA.","Tempting if you reverse the word but swap the middle L and P while writing it out.","Tempting if you reverse only the first three letters correctly and then lose track of the order.","Tempting if you assume only the last two letters swap, instead of checking first and last letters."]},
{id:"logic-104",topic:"Logical",difficulty:1,q:"Rahul walks 5 km north, turns right and walks 3 km, then turns right again and walks 5 km. Where is he now relative to his starting point?",o:["5 km North","3 km West","3 km East","8 km East"],a:2,e:"The two 5 km legs (north then south) cancel, leaving only the 3 km walked east.",tip:"Cancel opposite legs first; whatever remains is the displacement.",why:["Tempting if you track only the first 5 km leg and lose the later turns.","Tempting if you confuse right with left: turning right from north faces east, not west.","Correct: the north and south 5 km legs cancel, leaving 3 km east of the start.","Tempting if you add distances (5 + 3) instead of cancelling opposite legs for displacement."]},
{id:"logic-105",topic:"Logical",difficulty:1,q:"Pointing to a boy, Riya, a girl, says, 'He is the son of my mother's only son.' How is the boy related to Riya?",o:["Brother","Nephew","Son","Cousin"],a:1,e:"Riya is a girl, so her mother's only son is her brother, and his son is her nephew.",tip:"Collapse the chain from the speaker outward, one link at a time.",why:["Tempting if you stop one link early: the mother's only son is Riya's brother, but the boy is his son.","Correct: Riya's mother's only son is her brother, and his son is her nephew.","Tempting if you treat the speaker as male, so the 'only son' becomes the speaker; Riya is a girl.","Tempting if you drop a generation: a brother's son is a nephew, not a cousin."]},
{id:"logic-106",topic:"Logical",difficulty:1,q:"Doctor : Hospital :: Teacher : ?",o:["Student","School","Book","Library"],a:1,e:"A doctor works in a hospital; a teacher works in a school.",tip:"State the relation as a sentence, then apply it to the second pair.",why:["Tempting because a teacher works with students, but the relation is person to workplace, not person to client.","Correct: a doctor works in a hospital, and a teacher works in a school.","Tempting as a teacher's tool, but the pair links a professional with a workplace, not an object.","Tempting as a place of learning, but it is a librarian's workplace, not a teacher's."]},
{id:"logic-107",topic:"Logical",difficulty:1,q:"Which one is the odd one out: Triangle, Square, Pentagon, Cube?",o:["Triangle","Square","Pentagon","Cube"],a:3,e:"Triangle, square and pentagon are flat 2D shapes; a cube is a 3D solid.",tip:"Look for the category shared by three items and missing from one.",why:["Tempting as the shape with the fewest sides, a surface feature that ignores the 2D/3D split.","Tempting because it is the only one with right angles, but the real split is 2D versus 3D: a cube is the only solid.","Tempting as the one with five sides, but like the triangle and square it is a flat 2D figure.","Correct: triangle, square and pentagon are 2D shapes; a cube is a 3D solid."]},
{id:"logic-108",topic:"Logical",difficulty:1,q:"If 1 March of a year is a Monday, what day of the week is 29 March of the same year?",o:["Sunday","Tuesday","Monday","Wednesday"],a:2,e:"29 March is 28 days later, and 28 is a multiple of 7, so it is also a Monday.",tip:"Days that differ by a multiple of 7 fall on the same weekday.",why:["Tempting if you count 27 days (off-by-one), which moves the weekday back one to Sunday.","Tempting if you count 29 days by including both dates (inclusive range), giving remainder 1.","Correct: 29 March is 28 days later and 28 is a multiple of 7, so it is also a Monday.","Tempting if you count inclusively and add an extra day, getting 30 days and remainder 2."]},
{id:"logic-109",topic:"Logical",difficulty:2,q:"Find the next number: 2, 5, 11, 23, 47, ?",o:["94","95","96","93"],a:1,e:"Each term is double the previous plus 1: 47 x 2 + 1 = 95.",tip:"When terms roughly double, test x2 plus or minus a constant.",why:["Tempting if you double 47 but forget the +1 in the rule (47 x 2 = 94).","Correct: each term is double the previous plus 1, so 47 x 2 + 1 = 95.","Tempting if you add 2 after doubling (47 x 2 + 2), misreading the constant.","Tempting if you subtract 1 after doubling (47 x 2 - 1), flipping the sign of the constant."]},
{id:"logic-110",topic:"Logical",difficulty:2,q:"Find the next letter: Z, X, U, Q, ?",o:["M","K","L","N"],a:2,e:"Positions are 26, 24, 21, 17, falling by 2, 3, 4, so next falls by 5: 17 - 5 = 12 = L.",tip:"Write positions and check whether the gaps themselves form a pattern.",why:["Tempting if you repeat the last gap of 4 (17 - 4 = 13 = M) instead of increasing it to 5.","Tempting if you jump the gap to 6 (17 - 6 = 11 = K), skipping the -5 step.","Correct: positions 26, 24, 21, 17 fall by 2, 3, 4, so next is 17 - 5 = 12 = L.","Tempting if you reuse the gap of 3 (17 - 3 = 14 = N) instead of the growing gap."]},
{id:"logic-111",topic:"Logical",difficulty:2,q:"If CAT is coded as 24 (sum of letter positions, A=1, B=2, ...), what is the code for DOG?",o:["24","25","27","26"],a:3,e:"D=4, O=15, G=7, and 4 + 15 + 7 = 26.",tip:"Memorise EJOTY = 5, 10, 15, 20, 25 to find letter positions fast.",why:["Tempting if you copy CAT's code without recomputing; DOG's letters sum differently.","Tempting if you miscount O as 14 instead of 15 (4 + 14 + 7 = 25).","Tempting if you miscount O as 16 instead of 15 (4 + 16 + 7 = 27).","Correct: D = 4, O = 15, G = 7, and 4 + 15 + 7 = 26."]},
{id:"logic-112",topic:"Logical",difficulty:2,q:"A is the brother of B. B is the daughter of C. D is the father of C. How is A related to D?",o:["Grandson","Son","Nephew","Son-in-law"],a:0,e:"A and B are children of C, and D is C's father, so A (male) is D's grandson.",tip:"Draw a quick family tree: generations down, siblings sideways.",why:["Correct: A and B are C's children and D is C's father, so A (male) is D's grandson.","Tempting if you skip a generation and treat A as C's sibling rather than C's child.","Tempting if you treat D as C's brother instead of C's father, shifting A sideways.","Tempting if you misread 'brother of B' as a marriage link, but no in-law relation is given."]},
{id:"logic-113",topic:"Logical",difficulty:2,q:"Meera faces North. She turns 90 degrees clockwise, then 180 degrees clockwise, then 90 degrees anticlockwise. Which direction is she facing now?",o:["North","East","West","South"],a:3,e:"Net turn = 90 + 180 - 90 = 180 degrees clockwise, so she faces South.",tip:"Add clockwise turns, subtract anticlockwise ones, then apply the net turn.",why:["Tempting if you add the anticlockwise turn instead of subtracting it: 90 + 180 + 90 = 360, back to North.","Tempting if you apply only the first 90-degree turn and stop.","Tempting if you drop the final 90-degree anticlockwise turn: 90 + 180 = 270 clockwise is West.","Correct: net turn is 90 + 180 - 90 = 180 degrees clockwise, so she faces South."]},
{id:"logic-114",topic:"Logical",difficulty:2,q:"P, Q, R, S and T sit in a row facing north. R is at the extreme left end. T is in the middle. S sits next to R. Q is immediately to the right of P. Who sits at the extreme right end?",o:["P","R","Q","T"],a:2,e:"Order from left: R, S, T, then P and Q must take seats 4 and 5 with Q to the right of P, giving R S T P Q.",tip:"Fix the end and middle positions first, then place the pairs.",why:["Tempting if you place Q to the left of P, reversing 'immediately to the right'.","Tempting if you confuse the two ends of the row; R is at the extreme left, not the right.","Correct: the only order is R, S, T, P, Q, so Q is at the extreme right.","Tempting because T is fixed first, but T is in the middle seat, not at the end."]},
{id:"logic-115",topic:"Logical",difficulty:2,q:"Statements: All pens are books. All books are tables. Conclusions: I. All pens are tables. II. Some tables are pens. Which conclusion(s) follow?",o:["Only I follows","Only II follows","Both I and II follow","Neither follows"],a:2,e:"All pens are books and all books are tables, so all pens are tables (I). Converting 'All pens are tables' gives 'Some tables are pens' (II).",tip:"All A are B and all B are C gives all A are C, and 'All A are C' always converts to 'Some C are A'.",why:["Tempting if you forget that 'All pens are tables' converts to 'Some tables are pens'.","Tempting if you doubt the chain of two 'all' statements yet accept the weaker 'some' form.","Correct: the 'all' chain gives I, and converting I gives II, so both follow.","Tempting if you treat any two-step syllogism as uncertain, but an 'all-all' chain is always valid."]},
{id:"logic-116",topic:"Logical",difficulty:2,q:"What is the angle between the hour and minute hands of a clock at 4:20?",o:["0 degrees","10 degrees","20 degrees","130 degrees"],a:1,e:"Angle = |30 x 4 - 5.5 x 20| = |120 - 110| = 10 degrees.",tip:"Angle = |30H - 5.5M|; subtract from 360 if it exceeds 180.",why:["Tempting if you keep the hour hand exactly on 4, but it moves 10 degrees in 20 minutes.","Correct: |30 x 4 - 5.5 x 20| = |120 - 110| = 10 degrees.","Tempting if you use 5 instead of 5.5 per minute: |120 - 100| = 20.","Tempting if you report the hour hand's position (120 + 10 = 130) instead of the gap between hands."]},
{id:"logic-117",topic:"Logical",difficulty:2,q:"In a class, Amit is 12th from the top and 18th from the bottom. How many students are in the class?",o:["28","29","30","31"],a:1,e:"Total = 12 + 18 - 1 = 29, since Amit is counted twice.",tip:"Total = rank from top + rank from bottom - 1.",why:["Tempting if you subtract 2 instead of 1, over-correcting for the double count.","Correct: 12 + 18 - 1 = 29, because Amit is counted in both ranks.","Tempting if you just add the ranks (12 + 18) and count Amit twice.","Tempting if you add 1 instead of subtracting it, reversing the double-count correction."]},
{id:"logic-118",topic:"Logical",difficulty:2,q:"If 10 January 2023 was a Tuesday, what day of the week was 10 January 2024?",o:["Wednesday","Thursday","Monday","Tuesday"],a:0,e:"2023 is not a leap year, so the gap is 365 days = 52 weeks + 1 day, moving the weekday forward by one.",tip:"A normal year shifts the weekday by 1, a leap year (crossing 29 Feb) by 2.",why:["Correct: 2023 has 365 days = 52 weeks + 1 day, so Tuesday moves forward one to Wednesday.","Tempting if you add 2 because 2024 is a leap year, but 29 Feb 2024 falls after 10 January.","Tempting if you shift the weekday backward instead of forward by the extra day.","Tempting if you treat 365 days as exact weeks, forgetting the 1 extra day."]},
{id:"logic-119",topic:"Logical",difficulty:3,q:"Find the next number: 3, 4, 8, 17, 33, ?",o:["49","56","58","60"],a:2,e:"Differences are 1, 4, 9, 16, the perfect squares, so the next difference is 25: 33 + 25 = 58.",tip:"If differences are irregular, check whether they are squares or cubes.",why:["Tempting if you repeat the last difference of 16 (33 + 16) instead of the next square.","Tempting if you see second differences 3, 5, 7 but repeat 7: 33 + 16 + 7 = 56.","Correct: differences 1, 4, 9, 16 are squares, so the next is 25: 33 + 25 = 58.","Tempting if you switch to cubes and add 27 (33 + 27) instead of the square 25."]},
{id:"logic-120",topic:"Logical",difficulty:3,q:"In a code, FRIEND is written as HUMJTK. How is CANDLE written in that code?",o:["EDRIRL","EDRJRL","ECRIRL","EDQIRL"],a:0,e:"Letters are shifted by +2, +3, +4, +5, +6, +7 in turn: C+2=E, A+3=D, N+4=R, D+5=I, L+6=R, E+7=L.",tip:"Compute the shift for each position separately when one fixed shift fails.",why:["Correct: shifts +2 to +7 by position give C→E, A→D, N→R, D→I, L→R, E→L.","Tempting if you apply the wrong position's shift to D (+6, giving J instead of I).","Tempting if you assume a fixed +2 shift from the first letter and apply it to A (C instead of D).","Tempting if you reuse the second shift (+3) on N, giving Q instead of R."]},
{id:"logic-121",topic:"Logical",difficulty:3,q:"Six friends A, B, C, D, E and F sit around a circular table facing the centre. A sits opposite D. B is immediately to the right of A. C is immediately to the left of D. F is immediately to the left of A. Who sits opposite B?",o:["C","F","A","E"],a:3,e:"Placing A, then D opposite, B to A's right, C to D's left and F to A's left leaves E in the seat directly opposite B.",tip:"Fix one person, place the 'opposite' clue next, then fill neighbours.",why:["Tempting if you answer for F instead of B: C sits opposite F, not B.","Tempting if you confuse B and C: F sits opposite C, not B.","Tempting because A is B's neighbour, but neighbours are adjacent, never opposite.","Correct: seats run A, F, E, D, C, B round the table, so E is directly opposite B."]},
{id:"logic-122",topic:"Logical",difficulty:3,q:"If P x Q means P is the brother of Q, P + Q means P is the mother of Q, and P - Q means P is the father of Q, what does M + N x O - R mean?",o:["M is the mother of R","M is the aunt of R","M is the sister of R","M is the grandmother of R"],a:3,e:"M is mother of N, N is brother of O (so M is also O's mother), and O is father of R, so M is R's grandmother.",tip:"Decode left to right and track each person's generation.",why:["Tempting if you stop at O: M is O's mother, but O is R's father, adding a generation.","Tempting if you treat N's brother O as M's sibling, moving M sideways instead of up.","Tempting if you misread '+' as 'sister of', ignoring the defined symbol meanings.","Correct: M is mother of N and O, and O is R's father, so M is R's grandmother."]},
{id:"logic-123",topic:"Logical",difficulty:3,q:"At what time between 2 and 3 o'clock are the hour and minute hands of a clock exactly together?",o:["2:10 5/11","2:10","2:10 10/11","2:12"],a:2,e:"The hands coincide when 5.5M = 30 x 2, so M = 60/5.5 = 10 10/11 minutes past 2.",tip:"Hands coincide at 60H/11 minutes past H o'clock.",why:["Tempting if you close the 5-degree gap at 2:10 at 11 degrees per minute instead of 5.5, adding 5/11 not 10/11.","Tempting if you assume the hour hand stays on the 2, ignoring its 0.5 degrees per minute movement.","Correct: 5.5M = 60, so M = 60/5.5 = 120/11 = 10 10/11 minutes past 2.","Tempting if you use a relative speed of 5 instead of 5.5 degrees per minute: 60/5 = 12."]},
{id:"logic-124",topic:"Logical",difficulty:3,q:"Statements: Some doctors are singers. No singer is a dancer. Conclusions: I. Some doctors are not dancers. II. No doctor is a dancer. Which conclusion(s) follow?",o:["Only I follows","Only II follows","Both I and II follow","Neither follows"],a:0,e:"The doctors who are singers cannot be dancers, so some doctors are not dancers (I). Other doctors may still be dancers, so II does not follow.",tip:"Some A are B plus No B is C always gives Some A are not C, nothing stronger.",why:["Correct: the doctors who are singers cannot be dancers, so some doctors are not dancers; nothing more.","Tempting if you extend 'no singer is a dancer' to all doctors, though only some doctors are singers.","Tempting if you accept I and then overgeneralise it to II; 'some' cannot become 'no'.","Tempting if you think 'some' premises never give a definite conclusion, but I is forced."]},
{id:"logic-125",topic:"Logical",difficulty:3,q:"Among A, B, C, D and E, B is heavier than both A and E. C is heavier than B. D is lighter than A but heavier than E. Who is the second lightest?",o:["D","A","E","B"],a:0,e:"The order from heaviest is C, B, A, D, E, so the second lightest is D.",tip:"Chain the comparisons into one line, heaviest to lightest.",why:["Correct: the order is C, B, A, D, E from heaviest, so D is second lightest.","Tempting if you count up two from E but slip one place to the middle position (third lightest).","Tempting if you answer for the lightest instead of the second lightest.","Tempting if you read the chain from the wrong end: B is second heaviest, not second lightest."]},
{id:"verbal-001",topic:"Verbal",difficulty:1,q:"Choose the synonym of ABUNDANT.",o:["Scarce","Plentiful","Tiny","Abandoned"],a:1,e:"Abundant means existing in large quantities, so plentiful.",tip:"Rule out the antonym (scarce) first; the synonym is often its mirror.",why:["Tempting as the exact opposite: scarce means in short supply, the antonym trap in a synonym question.","Correct: abundant means present in large quantities, which is exactly plentiful.","Tempting if you confuse quantity with size; abundant is about how much there is, not how big.","Sound-alike trap: abandoned shares its opening letters with abundant but means deserted, not plentiful."]},
{id:"verbal-002",topic:"Verbal",difficulty:1,q:"Choose the antonym of BRIEF.",o:["Quick","Lengthy","Small","Concise"],a:1,e:"Brief means short in duration. The opposite is lengthy.",tip:"Say 'a brief meeting' vs 'a ___ meeting' to test each option.",why:["Near-synonym trap: quick, like brief, means short, so it is a synonym rather than the opposite.","Correct: brief means short in duration, and lengthy means long in duration, its direct opposite.","Tempting because brief and small both suggest little, but small is about size and is not an opposite.","Synonym trap: concise also means brief (short and to the point), so it cannot be the antonym."]},
{id:"verbal-101",topic:"Verbal",difficulty:1,q:"Choose the synonym of CANDID.",o:["Frank","Secretive","Sweet","Careful"],a:0,e:"Candid means open and honest in what one says, which is frank.",tip:"Picture 'a candid answer' and keep the option that fits the same sentence.",why:["Correct: candid means open and honest in speech, which is exactly frank.","Antonym trap: secretive is the opposite of candid, chosen by those who mix up synonym and antonym.","Sound-alike trap: candid resembles candy, which pulls you towards sweet, but the meanings are unrelated.","Tempting if you read candid as 'careful about what you say', but candid means the reverse: open and unguarded."]},
{id:"verbal-102",topic:"Verbal",difficulty:1,q:"Choose the antonym of TRANSPARENT.",o:["Clear","Opaque","Visible","Bright"],a:1,e:"Transparent means letting light through so you can see through it; opaque means not letting light through.",tip:"Eliminate options that mean the same as the target word (clear, visible) first.",why:["Synonym trap: clear means the same as transparent, so it is the opposite of what is asked.","Correct: transparent lets light through, while opaque blocks light completely.","Synonym trap: anything transparent can be seen through, so visible sits on the same side of the meaning.","Association trap: transparency is linked to light, but bright describes intensity, not see-through quality."]},
{id:"verbal-103",topic:"Verbal",difficulty:1,q:"Fill in the blank: She has been working here ___ 2019.",o:["for","since","from","by"],a:1,e:"With the present perfect, a starting point in time (2019) takes 'since'; 'for' is used with a length of time.",tip:"Point in time = since; length of time = for.",why:["Tempting because 'for' also goes with the present perfect, but only with a length of time (for five years).","Correct: 2019 is a point in time, and with the present perfect a starting point takes 'since'.","Tempting from 'from 2019 to 2022'; 'from' needs an end point and does not pair with 'has been working'.","Tempting from deadlines ('by 2019'), but 'by' marks a time limit, not the start of an ongoing action."]},
{id:"verbal-104",topic:"Verbal",difficulty:1,q:"Choose the correctly spelt word.",o:["Accomodate","Acommodate","Accommodate","Acomodate"],a:2,e:"The correct spelling has a double c and a double m: accommodate.",tip:"Accommodate is big enough to hold two c's and two m's.",why:["Common misspelling: doubling the c but not the m (one m) is the most frequent error with this word.","Common misspelling: doubling the m but not the c reverses the usual error and is still wrong.","Correct: accommodate has a double c and a double m.","Common misspelling: dropping both doubles (single c, single m) by spelling the word as it sounds."]},
{id:"verbal-105",topic:"Verbal",difficulty:1,q:"Choose the one word for: a person who loves books.",o:["Bibliophile","Philatelist","Numismatist","Lexicographer"],a:0,e:"Biblio means book and phile means lover, so a bibliophile loves books. A philatelist collects stamps, a numismatist collects coins, and a lexicographer compiles dictionaries.",tip:"Break the word into roots: biblio (book) + phile (lover).",why:["Correct: biblio (book) + phile (lover) gives a person who loves books.","Root trap: phil- (love) appears here too, but a philatelist collects stamps, not books.","Category trap: another collector word; a numismatist collects coins and currency, not books.","Association trap: a lexicographer works with words and compiles dictionaries, but need not love books."]},
{id:"verbal-106",topic:"Verbal",difficulty:1,q:"Complete the analogy. Pen : Write :: Knife : ___",o:["Sharp","Kitchen","Cut","Steel"],a:2,e:"A pen is used to write, and a knife is used to cut. The relation is tool to its function.",tip:"Say the relation as a sentence ('A pen is used to write') and apply it to the second pair.",why:["Attribute trap: sharp describes a quality of a knife, but the pair links a tool to its function.","Location trap: a knife is found in a kitchen, but a pen is not linked to its place, so the relation breaks.","Correct: a pen is used to write and a knife is used to cut (tool to function).","Material trap: steel is what a knife is made of, a different relation from tool to function."]},
{id:"verbal-107",topic:"Verbal",difficulty:1,q:"Choose the meaning of the idiom 'a piece of cake'.",o:["A small reward","A sweet surprise","A difficult task","Something very easy"],a:3,e:"'A piece of cake' describes something that is very easy to do.",tip:"Idioms are not literal; ignore the food and think of how the phrase is used: 'The test was a piece of cake.'",why:["Literal reading trap: a slice of cake can be a small treat, but the idiom is not about rewards.","Literal reading trap: cake is sweet, so 'sweet surprise' tempts those who read the food literally.","Antonym trap: a difficult task is the exact opposite of the idiom's meaning.","Correct: 'a piece of cake' is used for something very easy to do."]},
{id:"verbal-109",topic:"Verbal",difficulty:2,q:"Choose the synonym of METICULOUS.",o:["Careless","Painstaking","Hasty","Generous"],a:1,e:"Meticulous means showing great attention to detail, which is painstaking.",tip:"Spot the antonyms (careless, hasty) and remove them; the synonym is usually what remains on the same theme.",why:["Antonym trap: careless is the opposite of meticulous, chosen by those who mix up synonym and antonym.","Correct: meticulous means showing great attention to detail, which is painstaking.","Antonym trap: hasty work skips detail, the opposite of meticulous care.","Picked by those who only sense that meticulous is a compliment; generosity is a different virtue from attention to detail."]},
{id:"verbal-110",topic:"Verbal",difficulty:2,q:"Choose the antonym of EPHEMERAL.",o:["Transient","Fleeting","Brief","Permanent"],a:3,e:"Ephemeral means lasting a very short time; its opposite is permanent. Transient, fleeting and brief are all synonyms.",tip:"When three options mean roughly the same thing, the odd one out is often the antonym.",why:["Synonym trap: transient means short-lived, the same as ephemeral, not its opposite.","Synonym trap: fleeting means passing quickly, another word for ephemeral.","Synonym trap: brief means short in duration, which agrees with ephemeral rather than opposing it.","Correct: ephemeral means lasting a very short time; permanent means lasting indefinitely."]},
{id:"verbal-111",topic:"Verbal",difficulty:2,q:"Fill in the blank with the correct preposition: He was accused ___ stealing the documents.",o:["for","with","of","about"],a:2,e:"The verb 'accuse' takes the preposition 'of': accused of a crime.",tip:"Memorise fixed pairs: accuse of, charge with, blame for.",why:["Collocation trap: confused with 'blamed for' or 'arrested for'; accuse itself does not take 'for'.","Collocation trap: confused with 'charged with', which has a similar meaning but a different preposition.","Correct: the verb accuse takes the fixed preposition 'of' (accused of stealing).","Tempting by analogy with 'complain about', but 'about' never follows accuse in this sense."]},
{id:"verbal-112",topic:"Verbal",difficulty:2,q:"Spot the part of the sentence with an error: One of my friends / have bought / a new car.",o:["One of my friends","have bought","a new car","No error"],a:1,e:"The subject is 'One' (singular), so the verb must be 'has bought', not 'have bought'.",tip:"'One of the + plural noun' still takes a singular verb, because the subject is 'one'.",why:["Tempting because 'friends' is plural, but 'one of my friends' is a correct subject phrase.","Correct: the subject is 'one' (singular), so the verb must be 'has bought'; 'have' agrees with 'friends'.","Tempting to look for an article problem, but 'a new car' is correct as written.","Proximity trap: the plural noun 'friends' sits next to 'have', so the agreement error goes unnoticed."]},
{id:"verbal-113",topic:"Verbal",difficulty:2,q:"Choose the best replacement for the part in capitals: IF I WOULD HAVE KNOWN, I would have helped you.",o:["If I knew","If I have known","If I had known","No improvement"],a:2,e:"In a third conditional (unreal past), the if-clause uses the past perfect: If I had known, I would have helped.",tip:"Never put 'would' in the if-clause; past regret = if + had + past participle.",why:["Tense trap: 'If I knew' is the second conditional (present unreal), which clashes with 'would have helped'.","Tense trap: the present perfect is never used in an unreal conditional clause.","Correct: a third conditional needs the past perfect in the if-clause: If I had known.","Tempting because 'would have known' is common in speech, but 'would' does not belong in the if-clause."]},
{id:"verbal-114",topic:"Verbal",difficulty:2,q:"Choose the correct passive form: The committee will announce the results tomorrow.",o:["The results will be announced by the committee tomorrow.","The results would be announced by the committee tomorrow.","The results will announce by the committee tomorrow.","The results are announced by the committee tomorrow."],a:0,e:"Future simple 'will announce' becomes 'will be announced' in the passive; the tense must stay the same.",tip:"Keep the tense of the original verb and add 'be' + past participle.",why:["Correct: 'will announce' becomes 'will be announced', keeping the future tense and adding be + past participle.","Tense trap: 'would' shifts the future to the conditional, changing the meaning of the sentence.","Structure trap: 'be' is missing, so the sentence wrongly says the results will do the announcing.","Tense trap: the present simple drops the future 'will', although the action is still tomorrow."]},
{id:"verbal-115",topic:"Verbal",difficulty:2,q:"Choose the one word for: government by a small group of people.",o:["Oligarchy","Democracy","Monarchy","Anarchy"],a:0,e:"Oligarchy comes from Greek oligos (few) and archy (rule), meaning rule by a few.",tip:"-archy means rule; the prefix tells you by whom (mon = one, olig = few, an = none).",why:["Correct: olig- (few) + -archy (rule) means government by a small group.","Root trap: democracy is rule by the people (demos), the many rather than the few.","Root trap: mon- means one, so monarchy is rule by a single person, not a small group.","Root trap: an- means without, so anarchy is the absence of government, not rule by a few."]},
{id:"verbal-116",topic:"Verbal",difficulty:2,q:"Choose the meaning of the idiom 'to burn the midnight oil'.",o:["To waste resources","To start a quarrel","To celebrate","To work late into the night"],a:3,e:"The phrase means to stay up late working or studying, originally by the light of an oil lamp.",tip:"Picture the literal image (a lamp burning at midnight) and ask what activity it suggests.",why:["Literal reading trap: burning oil uses up fuel, so the image suggests waste, but the idiom means late work.","Idiom mix-up: confused with 'add fuel to the fire', which is about making a quarrel worse.","Literal reading trap: staying up past midnight suggests a party, but the idiom refers to working.","Correct: the phrase means working or studying late into the night, originally by an oil lamp."]},
{id:"verbal-117",topic:"Verbal",difficulty:2,q:"Complete the analogy. Ornithology : Birds :: Entomology : ___",o:["Words","Fossils","Fish","Insects"],a:3,e:"Ornithology is the study of birds and entomology is the study of insects. The study of word origins is etymology, a common trap.",tip:"Do not confuse entomology (insects) with etymology (word origins).",why:["Look-alike trap: etymology (word origins) is easily confused with entomology (insects).","Field trap: the study of fossils is palaeontology, another -ology that does not fit here.","Field trap: the study of fish is ichthyology; picked by those who recall only that it is an animal science.","Correct: ornithology studies birds and entomology studies insects."]},
{id:"verbal-118",topic:"Verbal",difficulty:2,q:"Which of the following words is spelt correctly?",o:["Occurence","Occurrence","Ocurrence","Occurrance"],a:1,e:"The correct spelling doubles both c and r and ends in -ence: occurrence.",tip:"Occur doubles its final r before -ence because the stress is on the last syllable (oc-CUR).",why:["Common misspelling: the r is not doubled, a frequent slip because 'occur' itself has one r.","Correct: occurrence doubles both c and r and ends in -ence.","Common misspelling: the c is not doubled, though 'occur' already has a double c.","Suffix trap: -ance is confused with -ence; the r is right but occurrence ends in -ence."]},
{id:"verbal-119",topic:"Verbal",difficulty:3,q:"Choose the synonym of OBSEQUIOUS.",o:["Servile","Stubborn","Obscure","Arrogant"],a:0,e:"Obsequious means excessively eager to please or obey, which is servile.",tip:"Do not be misled by look-alike words (obscure); think of the meaning 'too eager to please'.",why:["Correct: obsequious means excessively eager to please or obey, which is servile.","Look-alike trap: the 'ob-' opening recalls obstinate, which means stubborn, but obsequious is the opposite.","Look-alike trap: obscure shares the 'obs-' letters but means unclear or little known.","Antonym trap: arrogant is the opposite connotation; the obsequious person lowers rather than raises himself."]},
{id:"verbal-120",topic:"Verbal",difficulty:3,q:"Choose the antonym of LACONIC.",o:["Terse","Lazy","Calm","Verbose"],a:3,e:"Laconic means using very few words; its opposite is verbose, using too many words. Terse is a synonym.",tip:"Laconic comes from Laconia (Sparta), whose people were famous for short replies.",why:["Synonym trap: terse means using few words, the same as laconic, not its opposite.","Sound-alike trap: laconic is confused with lackadaisical or lax, which suggest laziness.","Connotation trap: a laconic person may seem calm, but laconic is about word count, not temperament.","Correct: laconic means using very few words; verbose means using too many."]},
{id:"verbal-122",topic:"Verbal",difficulty:3,q:"Spot the part of the sentence with an error: Hardly had he reached the station / than the train / started moving.",o:["Hardly had he reached the station","than the train","started moving","No error"],a:1,e:"'Hardly' is followed by 'when', not 'than': Hardly had he reached the station when the train started moving.",tip:"Hardly / scarcely ... when; no sooner ... than.",why:["Tempting because the inversion looks odd, but 'Hardly had he reached' is correct after a negative opener.","Correct: 'hardly' pairs with 'when', not 'than'; 'than' belongs with 'no sooner'.","Tempting to suspect a tense clash, but the simple past 'started moving' is correct here.","Pattern-mixing trap: 'no sooner ... than' makes 'hardly ... than' sound natural, hiding the error."]},
{id:"verbal-123",topic:"Verbal",difficulty:3,q:"Fill in the blank: Scarcely ___ the room when the lights went out.",o:["I had entered","did I entered","had I entered","I entered"],a:2,e:"When a sentence begins with the negative adverb 'scarcely', the subject and auxiliary are inverted: Scarcely had I entered ... when.",tip:"Negative opener (hardly, scarcely, never, seldom) = question-style word order.",why:["Word order trap: normal subject-first order is wrong after the negative opener 'scarcely'.","Verb form trap: inversion with 'did' needs the base form (did I enter), and the past perfect is needed here.","Correct: after 'scarcely' the auxiliary comes before the subject, with the past perfect: had I entered.","Word order and tense trap: no inversion, and the simple past loses the 'earlier action' sense."]},
{id:"verbal-124",topic:"Verbal",difficulty:3,q:"Choose the correct passive form: Who wrote this letter?",o:["By whom was this letter written?","Who was this letter written?","By whom this letter was written?","Who has written this letter by?"],a:0,e:"In the passive, 'who' becomes 'by whom', and the question keeps question word order with the same past tense: By whom was this letter written?",tip:"Who becomes 'by whom'; keep the tense and the question order (auxiliary before subject).",why:["Correct: 'who' becomes 'by whom', with question order (was + subject) and the same past tense.","Structure trap: 'by' is dropped, so the agent is lost and the question becomes ungrammatical.","Word order trap: statement order (subject before 'was') is wrong in a direct question.","Tense and structure trap: the tense shifts to present perfect and 'by' dangles at the end."]},
{id:"verbal-125",topic:"Verbal",difficulty:3,q:"Choose the one word for: a remedy for all diseases or difficulties.",o:["Placebo","Antidote","Panacea","Antiseptic"],a:2,e:"A panacea is a cure-all. An antidote counters a particular poison, and a placebo is a dummy treatment.",tip:"Pan means all (as in panorama, pandemic), so panacea = cure for all.",why:["Association trap: a placebo is linked with treatment, but it is a dummy remedy with no active effect, not a cure-all.","Near-synonym trap: an antidote counters one specific poison, not all diseases or difficulties.","Correct: pan- (all) + akos (remedy) gives panacea, a cure for everything.","Association trap: an antiseptic prevents infection on surfaces or wounds; it does not cure all ills."]},
{id:"di-001",topic:"DI",difficulty:1,q:"How many pens were sold in total from January to April?",o:["480","500","520","540"],a:1,e:"120 + 150 + 90 + 140 = 500.",tip:"Pair numbers that make round sums: 150 + 90 = 240, 120 + 140 = 260.",why:["Tempting if you read Apr's notebooks (120) instead of pens (140): 120+150+90+120 = 480.","Correct: 120 + 150 + 90 + 140 = 500 pens.","Tempting if you rush the pairing and take 150 + 90 as 260 instead of 240, giving 520.","Tempting if you misread Mar's 90 as 130 (an adjacent-value slip), giving 540."],data:{"headers":["Month","Pens","Notebooks"],"rows":[["Jan",120,80],["Feb",150,60],["Mar",90,100],["Apr",140,120]]}},
{id:"di-002",topic:"DI",difficulty:1,q:"In which month were combined sales of pens and notebooks the highest?",o:["Jan","Feb","Mar","Apr"],a:3,e:"Jan 200, Feb 210, Mar 190, Apr 260. April is highest.",tip:"Add each row once and compare; no need for exact totals if one row clearly leads.",why:["Jan's round 200 looks strong, but Feb (210) and Apr (260) have higher combined sales.","Tempting if you look at the pens column only: Feb has the most pens (150) but totals just 210.","Tempting if you pick the lowest combined total by mistake: Mar is 190, the smallest month.","Correct: combined sales are 200, 210, 190 and 260, so April (140 + 120) is highest."],data:{"headers":["Month","Pens","Notebooks"],"rows":[["Jan",120,80],["Feb",150,60],["Mar",90,100],["Apr",140,120]]}},
{id:"di-101",topic:"DI",difficulty:1,q:"What was the total number of laptops sold across all four quarters?",o:["1140","1080","1120","1160"],a:0,e:"240 + 300 + 270 + 330 = 1140 laptops.",tip:"Pair to round numbers: 240 + 330 = 570, 300 + 270 = 570.",why:["Correct: 240 + 300 + 270 + 330 = 1,140 laptops.","Tempting if you read Q1 tablets (180) for Q1 laptops, or take the Q3 row total (1,080) instead of the column.","Tempting if you misread Q4 laptops as 310 instead of 330, giving 1,120.","Tempting if you misread Q3 laptops as 290 instead of 270, giving 1,160."],data:{"headers":["Quarter","Laptops (units)","Tablets (units)","Phones (units)"],"rows":[["Q1",240,180,520],["Q2",300,150,480],["Q3",270,210,600],["Q4",330,240,640]]}},
{id:"di-102",topic:"DI",difficulty:2,q:"By what percentage did phone sales increase from Q1 to Q4 (to the nearest whole percent)?",o:["20%","23%","25%","19%"],a:1,e:"Increase = 640 - 520 = 120. 120 / 520 x 100 = 23.08%, about 23%.",tip:"Percent change = change / original value; always divide by the starting figure.",why:["Tempting if you divide the 120 increase by Q3's 600 (wrong row as base): 120/600 = 20%.","Correct: (640 - 520) / 520 = 23.08%, about 23%.","Tempting if you divide the 120 increase by Q2's 480 (wrong row as base): 120/480 = 25%.","Tempting if you divide by the final value instead of the original (wrong base): 120/640 = 18.75%."],data:{"headers":["Quarter","Laptops (units)","Tablets (units)","Phones (units)"],"rows":[["Q1",240,180,520],["Q2",300,150,480],["Q3",270,210,600],["Q4",330,240,640]]}},
{id:"di-103",topic:"DI",difficulty:3,q:"In Q3, what percentage of all units sold were tablets (to the nearest whole percent)?",o:["21%","24%","19%","22%"],a:2,e:"Q3 total = 270 + 210 + 600 = 1080. 210 / 1080 x 100 = 19.44%, about 19%.",tip:"Share = part / row total; 1080 x 0.2 = 216, so 210 is just under 20%.",why:["Tempting if you round the Q3 total to 1,000 for speed: 210/1000 = 21%.","Tempting if you divide tablets by the other products only (270 + 600 = 870): 210/870 = 24%.","Correct: 210 / (270 + 210 + 600) = 210/1080 = 19.44%, about 19%.","Tempting if you take Q4 tablets (240) by mistake: 240/1080 = 22% (wrong row)."],data:{"headers":["Quarter","Laptops (units)","Tablets (units)","Phones (units)"],"rows":[["Q1",240,180,520],["Q2",300,150,480],["Q3",270,210,600],["Q4",330,240,640]]}},
{id:"di-104",topic:"DI",difficulty:1,q:"What is the average Maths score of the five students?",o:["76","80","82","78"],a:3,e:"78 + 92 + 65 + 84 + 71 = 390. 390 / 5 = 78.",tip:"Use deviations from a guess of 80: -2 +12 -15 +4 -9 = -10, so average = 80 - 2 = 78.",why:["Tempting if you misread Bilal's 92 as 82, making the total 380 and the average 76.","Tempting if you average all three subjects (1,198/15 = 79.9) instead of the Maths column only.","Tempting if you average the English column instead (412/5 = 82.4): wrong column.","Correct: (78 + 92 + 65 + 84 + 71) / 5 = 390/5 = 78."],data:{"headers":["Student","Maths (out of 100)","Science (out of 100)","English (out of 100)"],"rows":[["Asha",78,85,72],["Bilal",92,74,81],["Chen",65,90,88],["Divya",84,79,95],["Eshan",71,68,76]]}},
{id:"di-105",topic:"DI",difficulty:1,q:"Which student has the highest total score across all three subjects?",o:["Divya","Bilal","Chen","Asha"],a:0,e:"Totals: Asha 235, Bilal 247, Chen 243, Divya 258, Eshan 215. Divya is highest.",tip:"Compare row totals; a single 95 plus two high-70s/80s usually wins.",why:["Correct: Divya totals 84 + 79 + 95 = 258, the highest of the five.","Tempting if you pick the top Maths score (92) or add only Maths + Science (166); Bilal totals 247.","Tempting if you add only Science + English (178, the highest pair) and skip Maths; Chen totals 243.","Tempting if you stop at the first strong row (Maths + Science = 163); Asha totals only 235."],data:{"headers":["Student","Maths (out of 100)","Science (out of 100)","English (out of 100)"],"rows":[["Asha",78,85,72],["Bilal",92,74,81],["Chen",65,90,88],["Divya",84,79,95],["Eshan",71,68,76]]}},
{id:"di-106",topic:"DI",difficulty:2,q:"How many students scored more than 75 in every one of the three subjects?",o:["0","1","2","3"],a:1,e:"Asha (72 English), Bilal (74 Science), Chen (65 Maths) and Eshan (71 Maths, 68 Science) each score 75 or below in at least one subject. Only Divya (84, 79, 95) qualifies: 1.",tip:"Look for the lowest score in each row; a row qualifies only if its minimum exceeds 75.",why:["Tempting if you use 80 as the cut-off: no student exceeds 80 in all three subjects.","Correct: only Divya (84, 79, 95) has every score above 75; each of the others has at least one score of 74 or below.","Tempting if you count Bilal, whose lowest score of 74 is just below 75 (a near-miss misread).","Tempting if you use 70 as the cut-off, which also admits Asha (min 72) and Bilal (min 74)."],data:{"headers":["Student","Maths (out of 100)","Science (out of 100)","English (out of 100)"],"rows":[["Asha",78,85,72],["Bilal",92,74,81],["Chen",65,90,88],["Divya",84,79,95],["Eshan",71,68,76]]}},
{id:"di-107",topic:"DI",difficulty:3,q:"What is the ratio of the total Science score to the total English score of all five students?",o:["97 : 103","103 : 99","99 : 103","99 : 101"],a:2,e:"Science total = 85 + 74 + 90 + 79 + 68 = 396. English total = 72 + 81 + 88 + 95 + 76 = 412. 396 : 412 = 99 : 103 (divide by 4).",tip:"Science total is smaller, so the first term must be smaller; that rules out reversed options fast.",why:["Tempting if you misread Eshan's Science 68 as 60, giving 388 : 412 = 97 : 103.","Tempting if you reverse the ratio and put English first: 412 : 396 = 103 : 99.","Correct: Science 396 : English 412; dividing both by 4 gives 99 : 103.","Tempting if you misread Chen's English 88 as 80, giving 396 : 404 = 99 : 101."],data:{"headers":["Student","Maths (out of 100)","Science (out of 100)","English (out of 100)"],"rows":[["Asha",78,85,72],["Bilal",92,74,81],["Chen",65,90,88],["Divya",84,79,95],["Eshan",71,68,76]]}},
{id:"di-108",topic:"DI",difficulty:1,q:"What was the total production of all three plants in 2023?",o:["1250","1340","1280","1300"],a:3,e:"480 + 460 + 360 = 1300 tonnes.",tip:"Add the two closest numbers first: 480 + 460 = 940, then + 360.",why:["Tempting if you take Plant B from the 2022 row (410): 480 + 410 + 360 = 1,250 (wrong row).","Tempting if you take Plant C from the 2024 row (400): 480 + 460 + 400 = 1,340 (wrong row).","Tempting if you take Plant B from the 2024 row (440): 480 + 440 + 360 = 1,280 (wrong row).","Correct: 2023 row total = 480 + 460 + 360 = 1,300 tonnes."],data:{"headers":["Year","Plant A (tonnes)","Plant B (tonnes)","Plant C (tonnes)"],"rows":[["2021",450,380,270],["2022",520,410,300],["2023",480,460,360],["2024",600,440,400]]}},
{id:"di-109",topic:"DI",difficulty:2,q:"Which plant had the highest percentage growth in production from 2021 to 2024?",o:["Plant C","Plant A","Plant B","All grew equally"],a:0,e:"A: 150/450 = 33.3%. B: 60/380 = 15.8%. C: 130/270 = 48.1%. Plant C grew fastest.",tip:"A smaller base with a large absolute increase gives the biggest percentage growth.",why:["Correct: Plant C grew 130/270 = 48.1%, ahead of A (33.3%) and B (15.8%).","Tempting if you compare absolute increases: Plant A gained the most tonnes (150) but grew only 33.3%.","Tempting if you reverse the ratio (2021/2024) and pick the largest, which actually flags the slowest grower.","Tempting if you only notice that all three plants rose over the period without comparing their rates."],data:{"headers":["Year","Plant A (tonnes)","Plant B (tonnes)","Plant C (tonnes)"],"rows":[["2021",450,380,270],["2022",520,410,300],["2023",480,460,360],["2024",600,440,400]]}},
{id:"di-110",topic:"DI",difficulty:2,q:"What was the average annual production of Plant C over the four years?",o:["330 tonnes","332.5 tonnes","335 tonnes","342.5 tonnes"],a:1,e:"270 + 300 + 360 + 400 = 1330. 1330 / 4 = 332.5 tonnes.",tip:"Average = total / count; 1330 / 4 = 332.5.",why:["Tempting if you take the median (300 + 360)/2 = 330 instead of the mean.","Correct: (270 + 300 + 360 + 400) / 4 = 1,330/4 = 332.5 tonnes.","Tempting if you average only the first and last years: (270 + 400)/2 = 335.","Tempting if you read Plant B's 2024 figure (440) for Plant C: 1,370/4 = 342.5 (wrong column)."],data:{"headers":["Year","Plant A (tonnes)","Plant B (tonnes)","Plant C (tonnes)"],"rows":[["2021",450,380,270],["2022",520,410,300],["2023",480,460,360],["2024",600,440,400]]}},
{id:"di-111",topic:"DI",difficulty:3,q:"In how many of the four years did Plant C account for more than 25% of the total production of the three plants?",o:["1","3","2","4"],a:2,e:"2021: 270/1100 = 24.5%. 2022: 300/1230 = 24.4%. 2023: 360/1300 = 27.7%. 2024: 400/1440 = 27.8%. Two years.",tip:"More than 25% means Plant C x 3 must exceed Plant A + Plant B.",why:["Tempting if you check only the latest year (2024, 27.8%) and miss 2023 (27.7%).","Tempting if you round 2021's 24.5% to 25% and treat 'more than' as 'at least'.","Correct: shares are 24.5%, 24.4%, 27.7% and 27.8%, so only 2023 and 2024 exceed 25%.","Tempting if you divide Plant C by A + B (the rest) instead of the total; every year then exceeds 25%."],data:{"headers":["Year","Plant A (tonnes)","Plant B (tonnes)","Plant C (tonnes)"],"rows":[["2021",450,380,270],["2022",520,410,300],["2023",480,460,360],["2024",600,440,400]]}},
{id:"di-112",topic:"DI",difficulty:1,q:"What were the total household expenses in February?",o:["2200","2300","2350","2250"],a:3,e:"1200 + 520 + 150 + 260 + 120 = 2250 dollars.",tip:"Group into round chunks: 1200 + (520 + 260) + (150 + 120) = 1200 + 780 + 270.",why:["Tempting if you total the January column (2,200) instead of February (wrong column).","Tempting if you round each item to the nearest hundred first (1200+500+200+300+100 = 2,300).","Tempting if you misread February Transport (150) as 250, adding 100 too much: 2,350.","Correct: 1200 + 520 + 150 + 260 + 120 = 2,250 dollars."],data:{"headers":["Category","January ($)","February ($)","March ($)"],"rows":[["Rent",1200,1200,1200],["Food",450,520,480],["Transport",180,150,210],["Utilities",220,260,190],["Leisure",150,120,240]]}},
{id:"di-113",topic:"DI",difficulty:2,q:"What percentage of March expenses was spent on Food (to the nearest whole percent)?",o:["21%","20%","43%","23%"],a:0,e:"March total = 1200 + 480 + 210 + 190 + 240 = 2320. 480 / 2320 x 100 = 20.69%, about 21%.",tip:"20% of 2320 is 464; 480 is a bit above, so the answer is just over 20%.",why:["Correct: 480 / 2,320 = 20.69%, which rounds to 21%.","Tempting if you round 20.69% down instead of to the nearest, or use January (450/2,200 = 20.5%).","Tempting if you leave rent out of the base: 480 / 1,120 = 42.9%, about 43%.","Tempting if you use the February column: 520 / 2,250 = 23.1% (wrong column)."],data:{"headers":["Category","January ($)","February ($)","March ($)"],"rows":[["Rent",1200,1200,1200],["Food",450,520,480],["Transport",180,150,210],["Utilities",220,260,190],["Leisure",150,120,240]]}},
{id:"di-114",topic:"DI",difficulty:2,q:"By what percentage did Leisure spending change from January to March?",o:["37.5% increase","60% increase","90% increase","160% increase"],a:1,e:"Leisure rose from 150 to 240, a change of 90. 90 / 150 x 100 = 60% increase.",tip:"Do not divide the new value by the old (that gives 160%); divide the change by the old value.",why:["Tempting if you divide the change by the new value (wrong base): 90/240 = 37.5%.","Correct: (240 - 150) / 150 = 90/150 = 60% increase.","Tempting if you report the absolute change of 90 dollars as if it were a percentage.","Tempting if you divide the new value by the old (240/150 = 160%) and forget to subtract 100%."],data:{"headers":["Category","January ($)","February ($)","March ($)"],"rows":[["Rent",1200,1200,1200],["Food",450,520,480],["Transport",180,150,210],["Utilities",220,260,190],["Leisure",150,120,240]]}},
{id:"di-115",topic:"DI",difficulty:1,q:"Which category had the largest absolute change in spending from January to February?",o:["Transport","Utilities","Food","Leisure"],a:2,e:"Changes: Rent 0, Food +70, Transport -30, Utilities +40, Leisure -30. Food changed the most.",tip:"Ignore the sign when asked for the absolute change.",why:["Tempting if you look for the biggest fall: Transport dropped 30, tied with Leisure, but Food rose 70.","Tempting if you rank only the increases by percentage: Utilities rose 18.2%, but only $40 in absolute terms.","Correct: Food changed by +70 (450 to 520), the largest absolute change.","Tempting if you compare January to March (Leisure +90) or by percentage (-20%) instead of Jan to Feb."],data:{"headers":["Category","January ($)","February ($)","March ($)"],"rows":[["Rent",1200,1200,1200],["Food",450,520,480],["Transport",180,150,210],["Utilities",220,260,190],["Leisure",150,120,240]]}},
{id:"di-116",topic:"DI",difficulty:2,q:"Which city had the highest percentage growth in population from 2010 to 2020?",o:["Northfield","Eastport","Westbrook","Southvale"],a:3,e:"Northfield 84/420 = 20%. Eastport 57/380 = 15%. Southvale 75/250 = 30%. Westbrook 61/610 = 10%. Southvale is highest.",tip:"Westbrook has the largest population but the smallest growth rate; base size matters.",why:["Tempting if you compare absolute growth: Northfield added the most (84 thousand) but grew only 20%.","Tempting if the jump from 380 to 437 across a hundred looks large; it is only 57/380 = 15%.","Tempting if you assume the largest city grew fastest; Westbrook grew just 61/610 = 10%.","Correct: Southvale grew 75/250 = 30%, the highest rate of the four."],data:{"headers":["City","Population 2010 (thousand)","Population 2020 (thousand)"],"rows":[["Northfield",420,504],["Eastport",380,437],["Southvale",250,325],["Westbrook",610,671]]}},
{id:"di-117",topic:"DI",difficulty:1,q:"What was the combined population of the four cities in 2020?",o:["1937 thousand","1897 thousand","1927 thousand","1967 thousand"],a:0,e:"504 + 437 + 325 + 671 = 1937 thousand.",tip:"All options end in 7, so compare tens and hundreds: pair up 504 + 437 = 941 and 325 + 671 = 996, then 941 + 996 = 1937.",why:["Correct: 504 + 437 + 325 + 671 = 1,937 thousand.","Tempting if you misread Eastport's 437 as 397, which lowers the sum by 40 to 1,897.","Tempting if you drop the units carry in 504 + 437 (writing 931, not 941), giving 1,927.","Tempting if you misread Eastport's 437 as 467, which raises the sum by 30 to 1,967."],data:{"headers":["City","Population 2010 (thousand)","Population 2020 (thousand)"],"rows":[["Northfield",420,504],["Eastport",380,437],["Southvale",250,325],["Westbrook",610,671]]}},
{id:"di-118",topic:"DI",difficulty:3,q:"By what percentage did the combined population of the four cities grow from 2010 to 2020 (to the nearest whole percent)?",o:["16%","17%","14%","19%"],a:1,e:"2010 total = 1660, 2020 total = 1937. Growth = 277 / 1660 x 100 = 16.69%, about 17%.",tip:"Never average the individual growth rates (that gives about 19%); use combined totals.",why:["Tempting if you round 16.69% down to 16% instead of to the nearest whole percent.","Correct: (1,937 - 1,660) / 1,660 = 277/1,660 = 16.69%, about 17%.","Tempting if you divide the growth by the 2020 total (wrong base): 277/1,937 = 14.3%.","Tempting if you average the four city rates (20, 15, 30, 10 = 18.75%) and ignore city sizes."],data:{"headers":["City","Population 2010 (thousand)","Population 2020 (thousand)"],"rows":[["Northfield",420,504],["Eastport",380,437],["Southvale",250,325],["Westbrook",610,671]]}},
{id:"di-119",topic:"DI",difficulty:3,q:"What percentage of all visits during the week came from mobile devices (to the nearest whole percent)?",o:["60%","62%","63%","65%"],a:2,e:"Mobile total = 338, desktop total = 200, overall = 538. 338 / 538 x 100 = 62.83%, about 63%.",tip:"Desktop is 200 of 538, about 37%, so mobile is about 63%.",why:["Tempting if you round the 538 total to 500: desktop 200/500 = 40%, so mobile looks like 60%.","Tempting if you truncate 62.83% to 62% instead of rounding to the nearest whole percent.","Correct: 338 / (200 + 338) = 338/538 = 62.83%, about 63%.","Tempting if you let Friday's high 70% mobile share drive a rough estimate instead of using column totals."],data:{"headers":["Day","Desktop visits (thousand)","Mobile visits (thousand)"],"rows":[["Mon",42,58],["Tue",38,64],["Wed",45,70],["Thu",40,66],["Fri",35,80]]}},
{id:"di-120",topic:"DI",difficulty:2,q:"What was the average total number of visits (desktop plus mobile) per day?",o:["105.4 thousand","108.2 thousand","67.6 thousand","107.6 thousand"],a:3,e:"Daily totals: 100, 102, 115, 106, 115. Sum = 538. 538 / 5 = 107.6 thousand.",tip:"Sum each column once (200 + 338 = 538) instead of adding row by row.",why:["Tempting if one daily total is added 11 short (sum 527 instead of 538), an addition slip.","Tempting if one figure is misread by 3 (sum 541 instead of 538), an addition slip.","Tempting if you average the mobile column only (338/5 = 67.6) and forget to add desktop.","Correct: total visits 200 + 338 = 538, and 538/5 = 107.6 thousand per day."],data:{"headers":["Day","Desktop visits (thousand)","Mobile visits (thousand)"],"rows":[["Mon",42,58],["Tue",38,64],["Wed",45,70],["Thu",40,66],["Fri",35,80]]}},
{id:"di-121",topic:"DI",difficulty:3,q:"On how many days were mobile visits more than 1.6 times desktop visits?",o:["3","1","2","4"],a:0,e:"1.6 x desktop: Mon 67.2 (58 no), Tue 60.8 (64 yes), Wed 72 (70 no), Thu 64 (66 yes), Fri 56 (80 yes). Three days.",tip:"Multiply desktop by 1.6 and compare, rather than dividing each pair.",why:["Correct: mobile exceeds 1.6 x desktop on Tue (64 > 60.8), Thu (66 > 64) and Fri (80 > 56).","Tempting if you count only Friday, the obvious outlier, and skip the close Tue and Thu checks.","Tempting if you dismiss Thursday's narrow margin (66 vs 64) as not exceeding the threshold.","Tempting if you round Wednesday's ratio 70/45 = 1.56 up to 1.6 and count it."],data:{"headers":["Day","Desktop visits (thousand)","Mobile visits (thousand)"],"rows":[["Mon",42,58],["Tue",38,64],["Wed",45,70],["Thu",40,66],["Fri",35,80]]}},
{id:"di-122",topic:"DI",difficulty:1,q:"How many people responded to the survey in total?",o:["560","600","580","620"],a:1,e:"Men = 120 + 80 + 60 + 40 = 300. Women = 90 + 110 + 75 + 25 = 300. Total = 600.",tip:"Total each column separately, then add the two column totals.",why:["Tempting if you skip the Men's Bicycle cell (40) when adding the column: 560.","Correct: Men 300 + Women 300 = 600 respondents.","Tempting if you misread Women's Train 75 as 55, making the women's total 280 and the sum 580.","Tempting if you misread Women's Bus 110 as 130, making the women's total 320 and the sum 620."],data:{"headers":["Preferred commute","Men (respondents)","Women (respondents)"],"rows":[["Car",120,90],["Bus",80,110],["Train",60,75],["Bicycle",40,25]]}},
{id:"di-123",topic:"DI",difficulty:2,q:"What percentage of women respondents prefer the bus (to the nearest whole percent)?",o:["58%","40%","37%","18%"],a:2,e:"Women total = 300. 110 / 300 x 100 = 36.67%, about 37%.",tip:"Percentage of women uses the women's column total as the base, not the overall total.",why:["Tempting if you use the bus row total as the base: 110/190 = 57.9% is the share of bus users who are women.","Tempting if you read the Car row for men instead (120/300 = 40%): wrong row and column.","Correct: 110 / 300 women = 36.67%, about 37%.","Tempting if you divide by all 600 respondents (110/600 = 18.3%) instead of the 300 women."],data:{"headers":["Preferred commute","Men (respondents)","Women (respondents)"],"rows":[["Car",120,90],["Bus",80,110],["Train",60,75],["Bicycle",40,25]]}},
{id:"di-124",topic:"DI",difficulty:2,q:"In which year was the profit margin (profit as a percentage of revenue) the highest?",o:["2021","2022","2020","2023"],a:3,e:"Profits: 170, 210, 210, 300. Margins: 20%, 22.8%, 20%, 25%. 2023 is highest.",tip:"Profit = revenue - cost; margin = profit / revenue.",why:["Tempting because 2021 has the second-best margin (210/920 = 22.8%), but 2023's 25% is higher.","Tempting if you see 2022 matching 2021's profit of 210; on higher revenue its margin is only 20%.","Tempting if you pick the year with the lowest cost (680); 2020's margin is only 170/850 = 20%.","Correct: margins are 20%, 22.8%, 20% and 25%, so 2023 (300/1,200) is highest."],data:{"headers":["Year","Revenue ($ thousand)","Cost ($ thousand)"],"rows":[["2020",850,680],["2021",920,710],["2022",1050,840],["2023",1200,900]]}},
{id:"di-125",topic:"DI",difficulty:3,q:"By what percentage did profit increase from 2020 to 2023 (to the nearest whole percent)?",o:["76%","41%","130%","43%"],a:0,e:"Profit 2020 = 850 - 680 = 170. Profit 2023 = 1200 - 900 = 300. Increase = 130 / 170 x 100 = 76.47%, about 76%.",tip:"Compute profit first; revenue growth (41%) is a trap.",why:["Correct: profit rose from 170 to 300; 130/170 = 76.47%, about 76%.","Tempting if you compute revenue growth instead of profit growth: 350/850 = 41%.","Reports the $130 thousand profit increase itself as a percentage instead of dividing it by 2020's profit (170).","Tempting if you divide the 130 increase by the 2023 profit (wrong base): 130/300 = 43%."],data:{"headers":["Year","Revenue ($ thousand)","Cost ($ thousand)"],"rows":[["2020",850,680],["2021",920,710],["2022",1050,840],["2023",1200,900]]}},
{id:"di-201",topic:"DI",difficulty:1,q:"Operating margin is (revenue - operating cost) / revenue. Which region had the highest operating margin in 2025?",o:["North","West","East","South"],a:2,e:"Margins 2025: North 13.5/54.0 = 25.0%, South 8.4/39.6 = 21.2%, East 8.5/30.5 = 27.9%, West 8.95/38.95 = 23.0%. East is highest.",tip:"A margin is a ratio: compute profit then divide by the same row's revenue for the same year.",why:["Mistake: picking the largest absolute profit ($13.5 million) instead of profit as a share of revenue. North is the biggest region, but its margin is only 25.0%.","Mistake: using the wrong column. Substituting 2024 revenue for 2025 revenue (41.0 - 30.0 = 11.0 on 41.0, about 26.8%) makes West look best.","Correct: East earns 30.5 - 22.0 = 8.5 on 30.5, a margin of about 27.9%, ahead of North (25.0%), West (23.0%) and South (21.2%).","Mistake: inverting the measure. South has the highest cost-to-revenue ratio (about 78.8%), which is the weakest margin, not the strongest."],data:{"headers":["Region","Revenue 2024 ($ million)","Revenue 2025 ($ million)","Operating cost 2025 ($ million)"],"rows":[["North",48,54,40.5],["South",36,39.6,31.2],["East",25,30.5,22],["West",41,38.95,30]]}},
{id:"di-202",topic:"DI",difficulty:2,q:"By what percentage did the combined revenue of all four regions change from 2024 to 2025, to one decimal place?",o:["8.7% increase","8.0% increase","9.9% increase","12.4% increase"],a:0,e:"2024 total = 150.00; 2025 total = 54.0 + 39.6 + 30.5 + 38.95 = 163.05. Change = 13.05 / 150.00 = 8.7%.",tip:"For a combined growth rate, add the totals first; never average the individual percentages.",why:["Correct: totals are 150.00 and 163.05, so the change is 13.05 / 150.00 = 8.7%.","Mistake: wrong base. Dividing the increase by the 2025 total (13.05 / 163.05) understates the growth.","Mistake: unweighted average of the regional growth rates (12.5%, 10%, 22%, -5%). Small East has the highest rate, so a simple average overstates total growth.","Mistake: averaging the regional rates and also treating West's 5% fall as a 5% rise; the sign error compounds the unweighted-average error."],data:{"headers":["Region","Revenue 2024 ($ million)","Revenue 2025 ($ million)","Operating cost 2025 ($ million)"],"rows":[["North",48,54,40.5],["South",36,39.6,31.2],["East",25,30.5,22],["West",41,38.95,30]]}},
{id:"di-203",topic:"DI",difficulty:3,q:"If North's revenue keeps growing each year at the same percentage rate as it did from 2024 to 2025, what will North's revenue be in 2028, to the nearest $0.1 million?",o:["$86.5 million","$68.3 million","$74.3 million","$76.9 million"],a:3,e:"Growth rate = (54.0 - 48.0) / 48.0 = 12.5%. 2028 is three years after 2025: 54.0 x 1.125^3 = 54.0 x 1.423828 = 76.9.",tip:"Number of growth periods = end year minus start year; compound by multiplying (1 + r) that many times.",why:["Mistake: off-by-one in periods. Counting 2025, 2026, 2027 and 2028 as four growth steps gives 54.0 x 1.125^4.","Mistake: off-by-one the other way, applying only two years of growth (54.0 x 1.125^2).","Mistake: simple instead of compound growth, adding 12.5% of 54.0 (6.75) three times and ignoring growth on growth.","Correct: the rate is 6/48 = 12.5%. From 2025 to 2028 is three years: 54.0 x 1.125^3 = 76.9."],data:{"headers":["Region","Revenue 2024 ($ million)","Revenue 2025 ($ million)","Operating cost 2025 ($ million)"],"rows":[["North",48,54,40.5],["South",36,39.6,31.2],["East",25,30.5,22],["West",41,38.95,30]]}},
{id:"di-204",topic:"DI",difficulty:1,q:"By what percentage did total headcount across all five departments change from 2024 to 2025, to one decimal place?",o:["3.6% increase","3.8% increase","9.4% increase","18.0% increase"],a:1,e:"2024 total = 480; 2025 total = 498. Change = 18 / 480 = 3.75%, i.e. 3.8% to one decimal place.",tip:"Percentage change = change / original value; total the column before calculating.",why:["Mistake: wrong base. Dividing the 18 extra staff by the new total (498) instead of the original 480.","Correct: totals are 480 and 498, so the change is 18 / 480 = 3.75%, which is 3.8%.","Mistake: unweighted average of the departmental changes (+15%, -10%, +20%, +12%, +10%). It ignores that Operations, the largest department, shrank.","Mistake: reading the absolute increase of 18 staff as a percentage."],data:{"headers":["Department","Staff 2024","Staff 2025","Average salary 2025 ($ thousand)"],"rows":[["Sales",120,138,52],["Operations",210,189,44],["Finance",45,54,68],["IT",75,84,75],["HR",30,33,50]]}},
{id:"di-205",topic:"DI",difficulty:2,q:"Finance's share of total company headcount changed between 2024 and 2025. By how many percentage points did it change, to one decimal place?",o:["Rose by 15.7 percentage points","Rose by 1.5 percentage points","Rose by 20.0 percentage points","Rose by 1.4 percentage points"],a:1,e:"Share 2024 = 45 / 480 = 9.375%. Share 2025 = 54 / 498 = 10.843%. Difference = 1.468 points, i.e. 1.5 percentage points.",tip:"Percentage points are a subtraction of two percentages; keep full precision until the final step.",why:["Mistake: confusing percent change with percentage points. 10.843 / 9.375 - 1 = 15.7% is the relative change in the share, not the difference in points.","Correct: the share went from 45/480 = 9.375% to 54/498 = 10.843%, a rise of 1.47 points, which is 1.5.","Mistake: using Finance's own headcount growth (45 to 54, +20%) instead of its share of the total.","Mistake: rounding too early. Rounding the shares to 9.4% and 10.8% before subtracting gives 1.4 instead of 1.5."],data:{"headers":["Department","Staff 2024","Staff 2025","Average salary 2025 ($ thousand)"],"rows":[["Sales",120,138,52],["Operations",210,189,44],["Finance",45,54,68],["IT",75,84,75],["HR",30,33,50]]}},
{id:"di-206",topic:"DI",difficulty:3,q:"What was the average salary per employee across the whole company in 2025, to the nearest $0.1 thousand?",o:["$57.8 thousand","$53.5 thousand","$56.5 thousand","$54.4 thousand"],a:3,e:"Salary bill = 138x52 + 189x44 + 54x68 + 84x75 + 33x50 = 7,176 + 8,316 + 3,672 + 6,300 + 1,650 = 27,114 ($ thousand). Average = 27,114 / 498 = 54.4.",tip:"A company-wide average from department averages must be weighted by headcount.",why:["Mistake: unweighted average of the five departmental averages. It gives small, highly paid IT and Finance the same weight as Operations.","Mistake: wrong column. Weighting the 2025 salaries by 2024 headcounts (25,665 / 480).","Mistake: mixing years. Dividing the correct 2025 salary bill by the 2024 headcount of 480.","Correct: the total salary bill is $27,114 thousand for 498 staff, so the average is 27,114 / 498 = 54.4."],data:{"headers":["Department","Staff 2024","Staff 2025","Average salary 2025 ($ thousand)"],"rows":[["Sales",120,138,52],["Operations",210,189,44],["Finance",45,54,68],["IT",75,84,75],["HR",30,33,50]]}},
{id:"di-207",topic:"DI",difficulty:2,q:"How did Company A's unit sales change from Q1 to Q4, to one decimal place?",o:["Rose by 10.0%","Fell by 12.0%","Fell by 3.0%","Rose by 9.1%"],a:0,e:"Q1 units = 0.25 x 800 = 200 thousand; Q4 units = 0.22 x 1,000 = 220 thousand. Change = 20 / 200 = +10.0%.",tip:"A falling share can hide rising sales: convert shares to units before comparing.",why:["Correct: units were 25% of 800 = 200 thousand in Q1 and 22% of 1,000 = 220 thousand in Q4, a rise of 20 / 200 = 10.0%.","Mistake: calculating the percent change of the share (25% to 22%) and ignoring that the market grew by 25%.","Mistake: treating the 3 percentage point fall in share as a 3% fall in sales.","Mistake: wrong base. Dividing the 20 thousand increase by the Q4 figure of 220 thousand."],data:{"headers":["Quarter (2025)","Total market (thousand units)","Company A share (%)","Company B share (%)","Company C share (%)"],"rows":[["Q1",800,25,30,20],["Q2",850,24,32,22],["Q3",900,26,30,21],["Q4",1000,22,34,24]]}},
{id:"di-208",topic:"DI",difficulty:3,q:"What was Company B's market share for 2025 as a whole (total units sold by B as a percentage of total market units), to one decimal place?",o:["31.5%","34.0%","31.6%","30.7%"],a:2,e:"B units: 0.30x800 = 240, 0.32x850 = 272, 0.30x900 = 270, 0.34x1,000 = 340; total 1,122. Market total = 3,550. Share = 31.6%.",tip:"An annual share is total units over total market, not the average of quarterly percentages.",why:["Mistake: unweighted average of the four quarterly shares. Q4, B's best quarter, is also the largest market, so a simple average understates the annual share.","Mistake: using only the latest quarter's share as if it described the whole year.","Correct: B sold 240 + 272 + 270 + 340 = 1,122 thousand of 3,550 thousand units, i.e. 31.6%.","Mistake: an inclusive-count error, totalling only Q1 to Q3 (782 / 2,550) and leaving out Q4."],data:{"headers":["Quarter (2025)","Total market (thousand units)","Company A share (%)","Company B share (%)","Company C share (%)"],"rows":[["Q1",800,25,30,20],["Q2",850,24,32,22],["Q3",900,26,30,21],["Q4",1000,22,34,24]]}},
{id:"di-209",topic:"DI",difficulty:1,q:"In Q3, how many more units did Company B sell than Company C, in thousands?",o:["9","90","810","81"],a:3,e:"B - C share in Q3 = 30% - 21% = 9%. Units = 0.09 x 900 = 81 thousand.",tip:"Differences in shares become units only after multiplying by the market size for that same period.",why:["Mistake: stopping at the share difference and reading 9 percentage points as 9 thousand units.","Mistake: wrong row. Applying the Q3 share gap to the Q4 market size of 1,000 thousand.","Mistake: a decimal slip, multiplying 900 by 0.9 instead of 0.09.","Correct: the share gap is 30% - 21% = 9 points, and 9% of the Q3 market of 900 thousand is 81 thousand units."],data:{"headers":["Quarter (2025)","Total market (thousand units)","Company A share (%)","Company B share (%)","Company C share (%)"],"rows":[["Q1",800,25,30,20],["Q2",850,24,32,22],["Q3",900,26,30,21],["Q4",1000,22,34,24]]}},
{id:"di-210",topic:"DI",difficulty:3,q:"What was the average compound quarterly growth rate of the total market from Q1 to Q4, to one decimal place?",o:["5.7%","7.7%","8.3%","6.3%"],a:1,e:"Total growth = 1,000 / 800 = 1.25 over three quarterly steps (Q1-Q2, Q2-Q3, Q3-Q4). Rate = 1.25^(1/3) - 1 = 0.0772 = 7.7%.",tip:"Four data points give three growth periods; take the root equal to the number of periods.",why:["Mistake: off-by-one in periods, counting four quarters as four growth steps: 1.25^(1/4) - 1.","Correct: Q1 to Q4 is three quarterly steps, so the rate is (1,000 / 800)^(1/3) - 1 = 7.7%.","Mistake: simple average, dividing the total growth of 25% by three without compounding.","Mistake: two errors at once, dividing the 25% total growth by four quarters and not compounding."],data:{"headers":["Quarter (2025)","Total market (thousand units)","Company A share (%)","Company B share (%)","Company C share (%)"],"rows":[["Q1",800,25,30,20],["Q2",850,24,32,22],["Q3",900,26,30,21],["Q4",1000,22,34,24]]}},
{id:"di-211",topic:"DI",difficulty:2,q:"Assume each annual budget is spread evenly across the 12 months. Measured against its budget for January to September, which cost line has the largest percentage overspend?",o:["Marketing","Travel","IT services","Facilities"],a:1,e:"Jan-Sep budgets (x 9/12): Marketing 720, Travel 180, Training 135, IT services 450, Facilities 1,080. Variances: +10%, +15%, -13.3%, +12%, -0.8%. Travel is highest.",tip:"Pro-rate the annual budget to the same period as the actuals before comparing.",why:["Mistake: choosing the largest absolute overspend ($72 thousand) instead of the largest percentage overspend. Marketing has the biggest budget, so its 10% looks large in dollars.","Correct: the Jan-Sep budget is 9/12 of 240 = 180, so 207 is 15% over. Marketing is 10% over, IT services 12% over.","Mistake: a near miss from estimating rather than calculating. IT services is 12% over ($54 thousand on $450 thousand), second to Travel.","Mistake: choosing the largest actual spend. Facilities spent $1,071 thousand against a Jan-Sep budget of $1,080 thousand, so it is slightly under budget."],data:{"headers":["Cost line","Annual budget ($ thousand)","Actual spend Jan-Sep ($ thousand)"],"rows":[["Marketing",960,792],["Travel",240,207],["Training",180,117],["IT services",600,504],["Facilities",1440,1071]]}},
{id:"di-212",topic:"DI",difficulty:1,q:"If Training continues to spend at its average monthly rate for January to September throughout October to December, by how much will it be under its annual budget?",o:["$24 thousand","$4.5 thousand","$18 thousand","$63 thousand"],a:0,e:"Monthly run-rate = 117 / 9 = 13. Full-year projection = 156. Under budget by 180 - 156 = 24 ($ thousand).",tip:"January to September inclusive is 9 months; count both ends.",why:["Correct: the monthly rate is 117 / 9 = 13, so the full year is 13 x 12 = 156, which is 180 - 156 = 24 under budget.","Mistake: off-by-one in months, treating January to September as 8 months (117 / 8 x 12 = 175.5).","Mistake: comparing only the Jan-Sep actual with the Jan-Sep budget (135 - 117) and not projecting the full year.","Mistake: taking the remaining budget (180 - 117) and ignoring the spending still to come in October to December."],data:{"headers":["Cost line","Annual budget ($ thousand)","Actual spend Jan-Sep ($ thousand)"],"rows":[["Marketing",960,792],["Travel",240,207],["Training",180,117],["IT services",600,504],["Facilities",1440,1071]]}},
{id:"di-213",topic:"DI",difficulty:3,q:"If every cost line continues at its January to September monthly rate for the rest of the year, by what percentage will total full-year spending exceed the total annual budget, to one decimal place?",o:["4.9%","4.7%","4.6%","18.0%"],a:0,e:"Total actual = 792 + 207 + 117 + 504 + 1,071 = 2,691. Projection = 2,691 x 12 / 9 = 3,588. Budget = 3,420. Overspend = 168 / 3,420 = 4.9%.",tip:"Total the column first, annualise once, then compare with the total budget as the base.",why:["Correct: actual Jan-Sep total is 2,691, projected full year 2,691 x 12/9 = 3,588, against a budget of 3,420. Overspend = 168 / 3,420 = 4.9%.","Mistake: wrong base. Dividing the 168 overspend by the projected spend of 3,588 instead of the budget.","Mistake: unweighted average of the five lines' percentage variances, which treats small Travel and Training like large Facilities.","Mistake: off-by-one in months, annualising with 12/8 instead of 12/9 (projecting 4,036.5)."],data:{"headers":["Cost line","Annual budget ($ thousand)","Actual spend Jan-Sep ($ thousand)"],"rows":[["Marketing",960,792],["Travel",240,207],["Training",180,117],["IT services",600,504],["Facilities",1440,1071]]}},
{id:"di-214",topic:"DI",difficulty:1,q:"Revenue equals units multiplied by price. Which product had the largest percentage increase in revenue from 2024 to 2025?",o:["Beta","Gamma","Delta","Alpha"],a:2,e:"Revenue ($ thousand) 2024 -> 2025: Alpha 1,000 -> 1,056 (+5.6%), Beta 1,200 -> 1,368 (+14%), Gamma 750 -> 756 (+0.8%), Delta 1,200 -> 1,440 (+20%).",tip:"Compute revenue for both years before comparing; volume and price can move in opposite directions.",why:["Mistake: comparing unit growth only. Beta's units rose 20%, but its price fell, so revenue rose only 14%.","Mistake: comparing price growth only. Gamma's price rose 12%, but units fell 10%, so revenue rose under 1%.","Correct: Delta revenue rose from 8 x 150 = 1,200 to 9 x 160 = 1,440 ($ thousand), an increase of 20%.","Mistake: choosing the largest absolute rise in units (+4 thousand). Alpha's price fell, so revenue rose only 5.6%."],data:{"headers":["Product","Units 2024 (thousand)","Price 2024 ($ per unit)","Units 2025 (thousand)","Price 2025 ($ per unit)"],"rows":[["Alpha",40,25,44,24],["Beta",15,80,18,76],["Gamma",60,12.5,54,14],["Delta",8,150,9,160]]}},
{id:"di-215",topic:"DI",difficulty:2,q:"By what percentage did total revenue from all four products change from 2024 to 2025, to one decimal place?",o:["10.2% increase","1.6% increase","11.3% increase","10.1% increase"],a:2,e:"2024 revenue = 1,000 + 1,200 + 750 + 1,200 = 4,150. 2025 revenue = 1,056 + 1,368 + 756 + 1,440 = 4,620. Change = 470 / 4,150 = 11.3%.",tip:"Derive revenue per product, sum, then calculate one percentage change on the totals.",why:["Mistake: wrong base. Dividing the $470 thousand increase by the 2025 total of 4,620.","Mistake: using total units (123 thousand to 125 thousand) instead of revenue, ignoring price changes.","Correct: total revenue rose from $4,150 thousand to $4,620 thousand: 470 / 4,150 = 11.3%.","Mistake: unweighted average of the four products' revenue growth rates (5.6%, 14%, 0.8%, 20%)."],data:{"headers":["Product","Units 2024 (thousand)","Price 2024 ($ per unit)","Units 2025 (thousand)","Price 2025 ($ per unit)"],"rows":[["Alpha",40,25,44,24],["Beta",15,80,18,76],["Gamma",60,12.5,54,14],["Delta",8,150,9,160]]}},
{id:"di-216",topic:"DI",difficulty:2,q:"What was the average revenue per unit across all products combined in 2025, to the nearest cent?",o:["$68.50","$34.31","$33.74","$36.96"],a:3,e:"2025 revenue = 44x24 + 18x76 + 54x14 + 9x160 = 1,056 + 1,368 + 756 + 1,440 = 4,620 ($ thousand). Units = 125 thousand. Average = $36.96.",tip:"Average price across products = total revenue / total units, never the mean of the prices.",why:["Mistake: unweighted average of the four prices. Expensive Delta sells few units, so a simple average greatly overstates the true figure.","Mistake: wrong column. Weighting 2025 prices by 2024 units (4,220 / 123).","Mistake: wrong year. This is the 2024 average (4,150 / 123).","Correct: total 2025 revenue is $4,620 thousand over 125 thousand units, so 4,620 / 125 = $36.96."],data:{"headers":["Product","Units 2024 (thousand)","Price 2024 ($ per unit)","Units 2025 (thousand)","Price 2025 ($ per unit)"],"rows":[["Alpha",40,25,44,24],["Beta",15,80,18,76],["Gamma",60,12.5,54,14],["Delta",8,150,9,160]]}},
{id:"di-217",topic:"DI",difficulty:2,q:"What percentage of all employees surveyed across the four sites were satisfied, to one decimal place?",o:["68.0%","54.5%","62.0%","65.8%"],a:3,e:"Satisfied counts: 0.72x250 = 180, 0.55x400 = 220, 0.64x150 = 96, 0.81x200 = 162; total 658 of 1,000 = 65.8%.",tip:"Convert each percentage to a head count using its group size, then divide by the total.",why:["Mistake: unweighted average of the four site percentages. It underweights Plant 1, the largest and least satisfied site.","Mistake: wrong column. This is the weighted result for 'Would recommend employer', not 'Satisfied'.","Mistake: leaving out a row. Using only the first three sites (496 / 800) omits Field sales.","Correct: satisfied employees are 180 + 220 + 96 + 162 = 658 out of 1,000, i.e. 65.8%."],data:{"headers":["Site","Employees surveyed","Satisfied (%)","Would recommend employer (%)"],"rows":[["Head office",250,72,60],["Plant 1",400,55,45],["Plant 2",150,64,50],["Field sales",200,81,70]]}},
{id:"di-218",topic:"DI",difficulty:3,q:"At Head office, 75% of the satisfied employees would recommend the employer. What percentage of all Head office employees surveyed would recommend the employer but are not satisfied, to the nearest whole percent?",o:["6%","10%","12%","25%"],a:0,e:"Satisfied = 0.72 x 250 = 180. Satisfied and recommend = 0.75 x 180 = 135. All recommenders = 0.60 x 250 = 150. Recommend but not satisfied = 15 = 6% of 250.",tip:"A percentage of a percentage needs converting to counts; keep track of which group is the base.",why:["Correct: 180 are satisfied and 75% of them (135) recommend. 60% of 250 = 150 recommend in total, so 15 recommend without being satisfied: 15 / 250 = 6%.","Mistake: wrong base. Expressing the 15 employees as a share of the 150 who recommend rather than of all 250 surveyed.","Mistake: subtracting the two column percentages (72% - 60%), which ignores the overlap between the groups.","Mistake: taking the 25% of satisfied employees who do not recommend, which answers a different question and is a percentage of a subgroup."],data:{"headers":["Site","Employees surveyed","Satisfied (%)","Would recommend employer (%)"],"rows":[["Head office",250,72,60],["Plant 1",400,55,45],["Plant 2",150,64,50],["Field sales",200,81,70]]}},
{id:"di-220",topic:"DI",difficulty:2,q:"Converting each year's sales at that year's exchange rate, by what percentage did the combined dollar sales of the three subsidiaries change from 2024 to 2025, to one decimal place?",o:["+10.4%","+0.2%","-0.3%","+13.8%"],a:2,e:"2024 ($ million): 66/1.20 = 55, 3,300/110 = 30, 450/6.0 = 75; total 160. 2025: 72/1.25 = 57.6, 3,600/120 = 30, 540/7.5 = 72; total 159.6. Change = -0.25%, i.e. -0.3%.",tip:"Convert to one currency at the right rate for each year before totalling; local amounts in different currencies cannot be added.",why:["Mistake: adding the local-currency figures (3,816 to 4,212) across different currencies, which ignores the exchange rates entirely.","Mistake: unweighted average of the three subsidiaries' dollar growth rates (+4.7%, 0%, -4.0%).","Correct: dollar sales were 55 + 30 + 75 = $160 million in 2024 and 57.6 + 30 + 72 = $159.6 million in 2025, a change of -0.4 / 160 = -0.3%.","Mistake: wrong column. Converting 2024 sales at 2025 rates as well, which applies the weaker currencies to both years and inflates growth."],data:{"headers":["Subsidiary","Sales 2024 (local currency, million)","Sales 2025 (local currency, million)","Exchange rate 2024 (local units per $1)","Exchange rate 2025 (local units per $1)"],"rows":[["X",66,72,1.2,1.25],["Y",3300,3600,110,120],["Z",450,540,6,7.5]]}},
{id:"sjt-201",topic:"SJT",difficulty:1,q:"You are on a supply chain rotation. You realise that a purchase order you raised last week shows 500 units instead of the 5,000 the plan required. The supplier has already started production and nobody else has noticed. What is the MOST effective response?",o:["Wait to see whether the shortfall is picked up in the next stock review, then deal with it as part of that process.","Contact the supplier quietly to amend the order and only mention it to your manager if it causes a delay or extra cost.","Tell your manager straight away, explain the error and its impact, and propose asking the supplier today to amend it.","Raise a second purchase order for the missing 4,500 units so the total is correct, without drawing attention to the first one."],a:2,e:"Take ownership of your own errors early and openly: tell the accountable person promptly and bring a proposed solution.",tip:"When you have made a mistake, the best answer usually combines owning it, informing the right person quickly and proposing a fix.",why:["Passive: the cheapest time to fix an order is before production finishes, and waiting lets a known problem grow.","Acts quickly, which is why it tempts, but hides an error with possible cost and supplier implications from the person accountable for the relationship.","Owns the mistake promptly and transparently, gives your manager what they need to judge the cost and supplier impact, and arrives with a fix rather than just a problem.","Looks like a neat fix but conceals the error, may cost more than amending the original run, and leaves a confusing record for others."]},
{id:"sjt-202",topic:"SJT",difficulty:2,q:"You compiled a cost report for a senior meeting tomorrow and circulated it to attendees this morning. You now find a formula error that understates costs by 8%. P: Send corrected figures to all attendees immediately and tell your manager afterwards. Q: Leave it, as 8% is within normal estimating tolerance. R: Tell your manager now, then with their agreement send corrected figures with a short note explaining the change. S: Quietly fix the file on the shared drive without notifying anyone. Which ranking is most effective (most to least)?",o:["R, P, S, Q","S, R, P, Q","P, R, S, Q","R, S, P, Q"],a:0,e:"Correct material errors openly and quickly, keeping your manager in the loop before senior stakeholders see the change.",tip:"Rank transparent fixes that involve the accountable person highest, and silent fixes or dismissals lowest.",why:["R corrects the error openly and keeps your manager informed before senior people see the change; P corrects openly but risks blindsiding your manager; S fixes the source but leaves attendees using wrong numbers; Q dismisses a material error altogether.","Puts concealment first; a quiet fix protects your reputation, not the decision, and is less effective than either open correction.","Speed tempts, but sending corrections to senior attendees before your manager knows can blindside them in the meeting; a quick conversation first costs little and is more effective.","Ranks a silent fix above an open correction; attendees who already downloaded the report would still use the wrong figures, so S is worse than P."]},
{id:"sjt-203",topic:"SJT",difficulty:1,q:"On a finance rotation, your manager needs your month-end reconciliation by 3pm for the close. At 11am a sales manager asks you to pull a client revenue report 'within the hour' for a client call tomorrow morning. You cannot finish both by 3pm. What is the MOST effective response?",o:["Ask your manager to decide which piece of work you should do first, since both requests seem urgent to the people asking.","Work on both in parallel, switching between them, and aim to finish each as close to its deadline as you can.","Do the sales report first as it is quicker and keeps a client call on track, then rush to finish the reconciliation.","Tell the sales manager you are committed to the close until 3pm and offer the report by end of today, before their call."],a:3,e:"Prioritise by real deadlines and consequences, and negotiate timing openly with the requester rather than overcommitting.",tip:"Check what the requester actually needs and by when; many conflicts dissolve once true deadlines are clear.",why:["Not harmful, but hands up a decision you can resolve yourself once you notice the report is not needed until tomorrow.","Avoids an uncomfortable conversation but risks missing both deadlines and lowering quality on the close.","Feels helpful but puts a hard financial close at risk for a request whose real deadline is tomorrow.","Protects the hard deadline while still meeting the sales manager's real need (the call is tomorrow), and communicates the plan clearly."]},
{id:"sjt-204",topic:"SJT",difficulty:2,q:"You return from two days of training to find: a client complaint assigned to you with a promised response by noon today, a request from your manager for slides needed on Thursday, about 60 unread emails, and a colleague asking for help with a routine task. It is 9am. What is the MOST effective response?",o:["Help the colleague first so they are not blocked, then start the complaint and work through emails afterwards.","Answer the complaint first, then scan emails for urgent items, give the colleague a time later today, and plan the slides.","Work through your emails from oldest to newest so nothing urgent is missed, then turn to the complaint and the other tasks.","Start with your manager's slides, since that request comes from your line manager, then move on to the complaint."],a:1,e:"Sequence work by commitment and urgency, not by seniority of requester or order of arrival.",tip:"Handle fixed, external commitments first, then triage quickly and tell others when you will get to them.",why:["Well intentioned, but a routine task can wait a few hours whereas the client commitment cannot.","Meets the firm commitment first, checks quickly for hidden urgencies, and gives everyone else a clear plan.","Feels thorough, but reading 60 emails in order risks breaking a promise to a client that has a fixed time.","Prioritises by seniority rather than urgency; the slides are not needed until Thursday while the client deadline is today."]},
{id:"sjt-205",topic:"SJT",difficulty:1,q:"You are running a small project to launch a new ordering form for three regional sales teams. On Tuesday, testing reveals a problem that will delay launch by two weeks. The sponsor, the head of sales, expects your regular update on Friday. What is the MOST effective response?",o:["Tell the regional teams first so they can adjust their plans, then give the sponsor the full picture on Friday.","Tell the sponsor now, explaining the cause, the revised date and what you are doing to limit the delay.","Wait for Friday's scheduled update, when you will have more detail on the cause and a firmer revised date.","Ask the team to work overtime to try to recover the original date, and only report a delay if that fails."],a:1,e:"Communicate significant bad news to key stakeholders early, with cause, impact and a plan.",tip:"Bad news does not improve with age: tell the person who owns the outcome first, and bring a plan.",why:["Communicates, but in the wrong order: the sponsor may hear the news second-hand from their own teams.","Gives the sponsor early warning so they can manage their own commitments, and shows control by pairing the bad news with a plan.","Tempting because it feels more complete, but sitting on known bad news for three days reduces the sponsor's room to react.","Optimistic effort can help, but hiding a likely delay while gambling on recovery leaves the sponsor exposed if it fails."]},
{id:"sjt-206",topic:"SJT",difficulty:2,q:"On a sales rotation, a client asks for their delivery date. Operations say a supplier problem will probably make it two to three weeks late, but they cannot yet confirm. P: Avoid contacting the client until operations confirm a date. Q: Explain the supplier issue, give the likely range, and commit to confirming a firm date by a set day after agreeing it with operations. R: Tell the client the order is on track and ask operations to prioritise it. S: Tell the client the order is delayed and that you will update them when you know more. Which ranking is most effective (most to least)?",o:["Q, P, S, R","P, Q, S, R","S, Q, P, R","Q, S, P, R"],a:3,e:"Keep clients informed honestly and early, sharing what you know, what you do not, and when you will update them.",tip:"Prefer responses that are honest, specific and include a committed next step; rank misleading statements lowest.",why:["Ranks silence above an honest warning; the client is better served knowing about the delay now, even without full detail.","Waiting for certainty feels safe but leaves the client to discover the delay themselves; any honest, timely update beats it.","S is honest, but without a range or a follow-up date the client cannot plan; Q gives them more and commits to a next step.","Q is honest, specific and owns the follow-up; S is honest but vague; P leaves the client uninformed; R gives the client false information."]},
{id:"sjt-207",topic:"SJT",difficulty:2,q:"You coordinate a project team. Two peers disagreed sharply in a meeting about how to analyse some data. A week later they avoid each other and their joint task is falling behind. You are not their line manager. What is the MOST effective response?",o:["Speak to each privately to understand their concerns, then bring them together to agree a way forward.","Report the situation to both line managers, explaining the impact on the task, so they can deal with it.","Review both approaches yourself, choose the stronger one, and tell them to proceed with it from today.","Leave them to sort it out, as they are both professionals and the tension may fade on its own."],a:0,e:"Resolve conflict directly and early by understanding each side and refocusing on shared goals before escalating.",tip:"Talk to the people involved first; escalate only if a direct, constructive approach does not work.",why:["Addresses the conflict early and at the right level: understanding both views privately first makes a joint conversation about the way forward far more likely to succeed.","Escalates before trying the obvious first step; it may also harden positions and damage trust in you as coordinator.","Decisive, but imposes an answer without understanding the disagreement and leaves the underlying tension unresolved.","Respects their autonomy but ignores a problem that is already affecting delivery, which you are responsible for coordinating."]},
{id:"sjt-208",topic:"SJT",difficulty:2,q:"A teammate on your project has delivered their section late three times, and you have stayed late each time to cover the gap. P: Point out the late deliveries in the team meeting so everyone understands the cause of delays. Q: Keep covering the gaps yourself so the project is not affected. R: Ask your manager to deal with their performance. S: Speak to them privately to understand what is causing the delays and agree realistic deadlines and any support. Which ranking is most effective (most to least)?",o:["S, P, R, Q","Q, S, R, P","S, R, Q, P","R, S, Q, P"],a:2,e:"Address recurring issues with a colleague directly and privately first, escalating only if that fails.",tip:"Rank the private, direct and supportive response highest and public blame lowest.",why:["Public criticism is ranked too high; naming someone in front of the team is likely to cause defensiveness and resentment.","Silently absorbing extra work feels like team spirit but lets the problem continue and leaves no one able to fix it.","S addresses the issue directly and supportively; R gets it addressed but skips talking to the person; Q hides a recurring problem and is unsustainable; P embarrasses a colleague publicly.","Escalating first feels safe, but going to the manager before talking to the teammate can damage trust and misses possible simple causes."]},
{id:"sjt-209",topic:"SJT",difficulty:1,q:"On a procurement rotation you are helping evaluate bids for a contract. One of the bidding suppliers sends you two concert tickets of significant value 'as thanks for your time'. What is the MOST effective response?",o:["Return the tickets with a polite note, without telling anyone at work, to avoid making a fuss.","Accept them, since you are junior, do not make the final decision and the supplier says they are just thanks.","Accept the tickets but declare them in the gifts register so the gift is on record and transparent.","Politely decline the tickets and tell your manager, recording the offer if the gifts policy requires it."],a:3,e:"Avoid conflicts of interest and be transparent about any attempt to influence a decision.",tip:"With gifts, decline anything that could influence a live decision and tell the right person; quiet handling is never as strong.",why:["Refusing is right, but keeping it quiet hides information your organisation needs about a supplier's conduct during a tender.","A rationalisation: your input still shapes the evaluation, and the gift creates a perceived conflict regardless of seniority.","Declaring is good practice, which is why it tempts, but accepting a valuable gift from a current bidder still compromises the evaluation.","Avoids any conflict of interest during a live tender and is transparent, protecting both you and the fairness of the process."]},
{id:"sjt-210",topic:"SJT",difficulty:3,q:"Your manager asks you to prepare the monthly on-time delivery figure for senior leaders and to classify six late deliveries as 'customer-caused', which would lift the figure from 91% to 95%. The records you have show the delays were caused by your own warehouse. What is the MOST effective response?",o:["Report the request to the compliance hotline straight away, without first discussing it with your manager.","Raise your concern with your manager, show the records, and suggest reporting 91% with an explanation.","Use your manager's figure but add a footnote giving the 91% calculation, so the true figure is on record.","Classify them as asked, since your manager is accountable for the report and may know more than you."],a:1,e:"Do not misreport data; challenge the request directly and constructively first, and escalate formally if it persists.",tip:"On integrity issues, never comply with misreporting, but start by raising it with the person directly unless that is unsafe or inappropriate.",why:["Integrity is right, but going straight to a formal channel skips a conversation that may reveal information you lack or resolve the issue; it is a step for if the manager insists.","Keeps the report accurate while giving your manager the chance to explain or reconsider, and offers a constructive way to present a weaker number with context.","A half-measure: it publishes a figure you believe is wrong and creates confusion rather than resolving the issue.","Following instructions feels safe, but knowingly misreporting makes you part of the misstatement."]},
{id:"sjt-211",topic:"SJT",difficulty:2,q:"You discover that last quarter's sales report, which earned your team praise, double-counted some orders because of a system issue, overstating results by about 6%. P: Leave it, since the system issue was not your fault. Q: Tell your manager with evidence and suggest correcting the report and checking whether other reports are affected. R: Tell your manager but suggest waiting until next quarter's report to adjust the figures quietly. S: Correct the figures in your own working files only and say nothing. Which ranking is most effective (most to least)?",o:["Q, S, R, P","S, Q, R, P","Q, R, S, P","R, Q, S, P"],a:2,e:"Correct known reporting errors promptly and transparently, whoever caused them.",tip:"Rank responses that inform the right person and fix the root cause highest; anything that conceals sits near the bottom.",why:["S is ranked above R, yet S tells no one; R at least informs your manager, who can then decide what to do.","Fixing your own files is not a correction; the official report stays wrong, so it cannot be the most effective response.","Q is transparent and fixes the root cause; R informs your manager but delays and hides the correction; S conceals the error from decision-makers; P ignores it entirely.","Delaying the correction may feel less embarrassing, but leaders could be relying on the overstated figure now; prompt correction is better."]},
{id:"sjt-212",topic:"SJT",difficulty:1,q:"You are the account contact for a client on your sales rotation. The client calls, angry that their latest invoice overcharges them. Invoicing is handled by the finance team. What is the MOST effective response?",o:["Acknowledge their frustration, confirm the details, get finance to review it and agree when you will update them.","Apologise, then give them the finance team's direct contact details so they can resolve it quickly with the experts.","Apologise and promise a credit note today for the overcharged amount so they feel the issue is resolved.","Explain that invoicing is a finance matter outside your control, but say you will pass on the message."],a:0,e:"Own the client's problem, gather facts and set clear expectations, even when another team must do the fix.",tip:"With unhappy customers, acknowledge, take ownership, involve the right team and commit to a follow-up time.",why:["Takes ownership of the client relationship, gathers the facts and sets a clear expectation while involving the team that can fix it.","Polite and efficient on paper, but it pushes the client away and gives up ownership of a relationship you are responsible for.","Reassuring, but commits to a credit you have not verified and may not have authority to give.","Honest about the process, but distances you from the problem and sounds like deflection to an unhappy client."]},
{id:"sjt-213",topic:"SJT",difficulty:3,q:"A long-standing client asks you to agree today to a product customisation for their next order. Operations tell you it is feasible but would delay several other clients' orders by about a week. The client is pressing for a yes on today's call. What is the MOST effective response?",o:["Say you will return tomorrow with options, explore a phased or later delivery with operations, and involve your manager on trade-offs.","Decline the request today, explaining that operations have said it would delay other clients' orders by a week.","Tell the client you will pass the request to your manager, who can weigh it against other clients and decide.","Agree to the customisation on the call to protect the relationship, then ask operations to find a way to make it work."],a:0,e:"Balance customer needs with wider commitments: avoid overpromising, explore options, and escalate only the decisions above your authority.",tip:"Prefer responses that buy a short, defined amount of time to find a realistic solution over an instant yes or no.",why:["Shows commitment to the client without overpromising, explores options with the people who know the constraints, and escalates only the trade-off that is above your level.","Honest, but closes the door without exploring alternatives that might satisfy everyone.","Involving your manager may be needed eventually, but handing it off immediately avoids the work of finding options yourself.","Pleases the client today but commits capacity you do not control and shifts the cost onto other clients."]},
{id:"sjt-214",topic:"SJT",difficulty:2,q:"You lead a cross-functional project. A finance analyst from another team, who does not report to you, has missed two deadlines for inputs because her own manager's work takes priority. The project's next milestone depends on her figures. What is the MOST effective response?",o:["Do the finance analysis yourself from the data you have, so the project milestone is not held up.","Remind her of the deadline in the project group chat so the whole team sees what the milestone is waiting on.","Ask about her workload, explain what the milestone needs, agree what she can deliver, and involve her manager with her if needed.","Ask her manager to make sure she meets your deadlines, explaining that the milestone depends on her figures."],a:2,e:"When leading without authority, influence through understanding, clear reasons and joint problem-solving.",tip:"Without formal authority, start with a direct conversation about the other person's constraints and the shared goal.",why:["Shows initiative but takes on work outside your expertise, risks errors and leaves the dependency problem unsolved.","Applies public pressure, which can feel effective, but is likely to damage goodwill with someone you rely on.","Builds the relationship, makes the dependency clear, and involves her manager jointly with her only if the priority clash cannot be solved between you.","May get results, but going over her head before talking to her risks resentment and ignores the real constraint."]},
{id:"sjt-215",topic:"SJT",difficulty:3,q:"You have been asked to get store managers, who are senior to you, to adopt a new stock-count process. Several are resisting. P: Accept that some stores will not adopt it and focus on the willing ones. Q: Ask the project sponsor to send a message reinforcing that the process is expected. R: Call the resistant managers to hear their concerns, adjust the process where reasonable, and share results from stores already using it. S: List the resisting managers by name, with critical comments, in your report to senior leaders without speaking to them first. Which ranking is most effective (most to least)?",o:["Q, P, R, S","R, Q, P, S","Q, R, P, S","R, P, Q, S"],a:1,e:"Influence senior or peer stakeholders by understanding objections and showing evidence, using sponsor authority as a back-up.",tip:"Without authority, rank listening and evidence above formal pressure, and both above giving up or public criticism.",why:["Leads with formal pressure and ranks giving up above listening to concerns, which is the step most likely to win genuine adoption from senior managers.","R influences through listening and evidence; Q uses legitimate authority to support adoption; P gives up on part of the goal; S undermines trust by criticising people behind their backs.","Sponsor backing can help, but using authority before understanding the resistance tends to produce grudging compliance, so it is a second step.","Giving up on resistant stores is ranked above seeking sponsor support, which still pursues the objective through a legitimate route."]},
{id:"sjt-216",topic:"SJT",difficulty:1,q:"After you present to a director, your manager tells you your slides were too detailed and you did not answer the director's main question directly. You had prepared thoroughly and feel the comment is a little unfair. What is the MOST effective response?",o:["Explain why you included the detail and how long you spent preparing, so your manager understands your reasoning.","Thank your manager, ask for specific examples and what a better answer would have been, and apply it next time.","Ask colleagues who were at the presentation whether they agree with your manager's view of how it went.","Thank your manager, accept the point, and move on to your next task without discussing it further."],a:1,e:"Receive feedback openly, clarify it so it becomes actionable, and show you have acted on it.",tip:"With feedback, prefer listening, asking for specifics and following up over defending or ignoring.",why:["Understandable, but comes across as defensive and shifts the conversation away from learning.","Treats feedback as useful information and makes it specific and actionable before applying it, rather than defending or ignoring it.","Seeking validation rather than improvement, and may undermine your manager.","Polite, but without clarifying the feedback you are unlikely to know exactly what to change."]},
{id:"sjt-217",topic:"SJT",difficulty:3,q:"Anonymous comments in your 360-degree review say you sometimes dismiss others' ideas in meetings. You do not recognise this in yourself. What is the MOST effective response?",o:["Treat it as one person's view, since most of your 360 feedback was positive and you do not recognise it.","Ask your manager or trusted colleagues for specific examples, and ask one of them to flag it if it happens again.","Apologise to the whole team at the next meeting for dismissing their ideas and promise to listen more.","Try to work out who made the comment so you can discuss it with them directly and understand exactly what happened."],a:1,e:"Treat feedback you do not recognise as a prompt to seek specifics, not as something to dismiss or overreact to.",tip:"When feedback surprises you, gather specific examples from trusted people before deciding what to change.",why:["Comforting, but dismisses a pattern others may also see and misses a chance to improve.","Takes the feedback seriously without assuming it is wrong, gathers specific evidence to understand it, and builds in a way to notice and change the behaviour.","Shows humility, but is a premature overreaction before you understand what the behaviour actually is.","Seems direct, but undermines the anonymity that makes 360 feedback honest and may feel intimidating."]},
{id:"sjt-218",topic:"SJT",difficulty:2,q:"On an operations rotation you notice that a safety barrier separating forklifts from a pedestrian walkway has been removed. The shift supervisor tells you it is 'temporary, to speed up loading' and carries on. What is the MOST effective response?",o:["Note the issue in your weekly rotation report so your manager can follow it up with the site team.","Put the barrier back yourself once the supervisor has moved on, so the walkway is protected again.","Tell the supervisor clearly that you disagree, then leave the decision with them as it is their area.","Raise it immediately with the site manager or safety lead so the area can be made safe now."],a:3,e:"Safety risks warrant prompt escalation to the appropriate authority when the person responsible will not act.",tip:"Escalate quickly when there is risk of harm; the usual 'talk to the person first' step can be very short.",why:["Records the concern, but days of delay are unacceptable for a hazard that could injure someone today.","Shows concern, but may interfere with an operation you are not trained in, can simply be undone, and avoids raising the issue properly.","Speaking up is good, but stopping there leaves a known safety risk in place when the supervisor has already dismissed it.","A live safety risk justifies prompt escalation once the person responsible has declined to act; it gets the right authority involved quickly."]},
{id:"sjt-219",topic:"SJT",difficulty:3,q:"Your manager is on leave for a week and has named a deputy for decisions. A key supplier emails to say prices will rise 4% next month and asks for a response within three days. P: Email the head of department directly for a decision. Q: Take no action until your manager returns, as pricing decisions are theirs. R: Accept the increase yourself to keep the relationship smooth. S: Acknowledge the email, say you will respond by the deadline, and brief the deputy on the impact. Which ranking is most effective (most to least)?",o:["P, S, Q, R","S, P, R, Q","Q, S, P, R","S, P, Q, R"],a:3,e:"Escalate to the right level: use the nominated decision-maker, act within deadlines, and never make decisions beyond your authority.",tip:"Proportionate escalation goes to the nearest person with the authority to decide, in time to matter.",why:["Skipping the deputy to go to the head of department is disproportionate when a nominated decision-maker is available.","Ranks accepting the increase above waiting. Waiting is weak because the three-day deadline passes while your manager is away, but R commits the company to extra cost without authority, which is worse; Q should rank above R.","Waiting for your manager respects their role but misses the supplier's deadline when someone else has been named to decide.","S uses the right person and meets the deadline; P gets a timely decision but escalates too high; Q misses the deadline; R exceeds your authority and commits cost."]},
{id:"sjt-220",topic:"SJT",difficulty:1,q:"A colleague on your team fills in a shared weekly spreadsheet slightly differently from the agreed template, which means you spend about 20 minutes each week reformatting it before you can use it. What is the MOST effective response?",o:["Mention it to them directly, explain the extra work, and ask whether something about the template is not working.","Keep reformatting it each week, as it only takes 20 minutes and raising it could create unnecessary friction in the team.","Raise it with your manager so the whole team is reminded at the next meeting to follow the agreed template.","Lock the template so it can only be completed in the agreed format, without discussing it with anyone first."],a:0,e:"Resolve minor working issues directly with the person involved before involving others.",tip:"Match the response to the size of the problem: small issues call for a direct, friendly conversation.",why:["Proportionate and direct: it raises a small issue with the person who can fix it and stays open to a genuine reason.","Avoids friction, but quietly accepts recurring waste that a short conversation could remove.","Escalates a minor issue that you can easily resolve yourself, which can seem petty.","Solves the symptom, but changes a shared tool unilaterally and may block a legitimate need."]},
{id:"sjt-221",topic:"SJT",difficulty:2,q:"In weekly team meetings, a recently joined colleague who works remotely is often talked over, and twice their suggestions were later presented as someone else's idea. What is the MOST effective response?",o:["Leave it, as they need to learn to speak up for themselves and will naturally settle in as they get to know the team.","Point out in the meeting, in front of everyone, the colleagues who keep talking over them or taking credit.","Tell the team leader what you have noticed so they can deal with it in the way they think best.","Credit their ideas by name in meetings, invite their input, and check privately how meetings feel for them."],a:3,e:"Promote inclusion through your own everyday actions first: give credit, create space, and fix team habits respectfully.",tip:"On inclusion, prefer practical actions you can take yourself, done respectfully, over passivity or public confrontation.",why:["Puts the burden on the person being excluded and lets an unfair pattern continue.","Well meant, but publicly calling people out is likely to cause defensiveness and may embarrass the colleague you want to support.","Involving the leader may help later, but passes the problem on without doing the simple things you could do yourself.","Acts within your own power straight away, supports the colleague respectfully and starts to change the meeting dynamic that is excluding them."]},
{id:"sjt-222",topic:"SJT",difficulty:2,q:"In the team group chat, a teammate posts a joke mocking a colleague's accent. A few people react with laughing emojis; the colleague does not respond. P: Message the teammate privately that the joke is hurtful and ask them to stop, check in with the colleague, and tell your manager if it continues. Q: Report it to your manager without speaking to anyone. R: Ignore it, as the colleague has not complained. S: Add a laughing reaction to keep the mood light. Which ranking is most effective (most to least)?",o:["P, R, Q, S","Q, P, R, S","P, Q, R, S","R, P, Q, S"],a:2,e:"Challenge disrespectful behaviour promptly and support the person affected, escalating if it continues.",tip:"Silence from the person targeted is not consent; rank responses that challenge and support highest and joining in lowest.",why:["Ignoring the joke is ranked above reporting it, yet silence lets disrespectful behaviour become normal.","Reporting is reasonable, but it skips a quick, direct challenge and checking on the colleague, which address the harm faster.","P challenges the behaviour, supports the colleague and has an escalation route; Q gets it addressed but less directly; R tolerates it; S actively endorses it.","The colleague's silence does not mean they are fine; doing nothing cannot be the most effective response."]},
{id:"sjt-223",topic:"SJT",difficulty:1,q:"Leadership has rejected a process-improvement proposal you spent several weeks preparing, citing budget constraints this year. What is the MOST effective response?",o:["Tell your team that leadership does not really value improvement ideas, so they know what to expect.","Ask for feedback on the decision, look for low-cost parts that could still go ahead, and agree next steps.","Accept the decision professionally and move on to other work without asking for any further discussion.","Send the same proposal to another senior leader who might be more supportive and willing to sponsor it this year."],a:1,e:"Respond to setbacks by seeking feedback, adapting and persisting through legitimate routes.",tip:"After a setback, prefer responses that learn, adapt and keep going over giving up, venting or working around decisions.",why:["Venting is understandable, but it undermines leadership and lowers team morale.","Accepts the decision constructively, learns from it, and keeps the useful parts of the work alive through legitimate routes.","Professional, but misses the chance to learn why and to salvage parts of the proposal.","Shows persistence, but goes around a decision already made and may damage trust."]},
{id:"sjt-224",topic:"SJT",difficulty:3,q:"A pilot you led with a client has produced poor results, partly because of your planning and partly because the client's data was incomplete. The client is disappointed and you feel demoralised. Your next meeting with them is tomorrow. What is the MOST effective response?",o:["Review what went wrong with your team, prepare an honest account and recovery plan, and ask your manager to check it.","Focus the meeting on the gaps in the client's data, since that was a major cause and they need to fix it before phase two.","Ask your manager to lead the meeting in your place, given how the pilot went and how you are feeling.","Offer the client the next phase free of charge to make up for the disappointment and keep the account."],a:0,e:"Respond to setbacks by owning your part, learning quickly and presenting a credible plan.",tip:"When something you led fails, the strongest response owns it, analyses it and comes back with a plan.",why:["Owns the outcome, turns the setback into a concrete plan, and uses your manager's experience before a sensitive meeting.","Partly true, but leading with the client's failings sounds defensive and ignores your own share of the problem.","Avoids a difficult conversation and signals to the client that you are not in control of your own project.","A generous gesture, but a commercial commitment you probably lack authority to make, and it does not fix the cause."]},
{id:"sjt-225",topic:"SJT",difficulty:3,q:"Your rotation manager has asked you to finish a cost analysis by Friday. A senior project sponsor from another department has also asked you for a market review by Friday. Doing both properly would take about twice the time you have. What is the MOST effective response?",o:["Prioritise the sponsor's review because they are more senior, and tell your manager about the clash once you deliver on Friday.","Work evenings and the weekend so that you complete both pieces of work on time and to a good standard.","Tell both now you cannot do both well by Friday, offer options, and ask your manager, who sets priorities, to agree the order.","Deliver both on Friday with less depth than planned, without flagging the shortcuts to either person."],a:2,e:"When priorities conflict, raise it early and transparently, and let the person who owns your priorities make the trade-off.",tip:"Flag capacity conflicts early with options; silently overworking or cutting corners is rarely the best answer.",why:["Decides by seniority and tells your manager too late for them to influence the outcome.","Shows commitment, but is not sustainable, risks quality in both and hides a capacity problem your manager should know about.","Surfaces the conflict early, offers options rather than just a problem, and lets the person responsible for your workload resolve the trade-off.","Meets the deadlines on paper but quietly lowers quality, leaving both stakeholders relying on weaker work."]}
];
